/*eslint-disable*/import type{Messages}from"@lingui/core";export const messages=JSON.parse("{\"+2yKCC\":[\"Четыре фразы, которые вы говорите\"],\"+7Yrar\":[\"Зафиксировать решение и превратить его в командное правило\"],\"+95ije\":[\"Часть поведения живёт сразу в нескольких папках — доставка вебхуков, auth-middleware, ретраи в очереди. Эти спеки самые ценные — их агенту тяжелее всего нагрепать.\"],\"+Hwmbm\":[\"Польза и ограничения\"],\"+J6iIV\":[\"Развивать\"],\"+LpR+/\":[\"Да. Плагин всегда использует тот archcore, который лежит в вашем PATH. Ставьте его как удобно: curl, PowerShell, сборка из исходников. Подробности на https://docs.archcore.ai/cli/install/.\"],\"+MRoDu\":[\"Проверить перед мержем\"],\"+P8YHk\":[\"Впервые про Archcore? Посмотрите, как выглядит неделя работы с ним.\"],\"+PNeqU\":[\"После запуска откройте <0>http://localhost</0> в браузере.\"],\"+X9C07\":[\"Четыре: /archcore:init (первичная настройка), /archcore:plan (от идеи до проработанного плана), /archcore:document (зафиксировать решение или описать существующий код) и /archcore:review (сверить изменения и документацию). Повседневный контекст не требует команд вовсе, потому что хуки подставляют нужные правила и спеки во время правок.\"],\"+ZLdUj\":[\"Агент читает проект и предлагает правило про стек, гайд по запуску, обзор архитектуры и спецификацию на каждый модуль, который меняется чаще прочих. Один предпросмотр, и ничего не пишется, пока вы не подтвердите.\"],\"+a8Tt5\":[\"ADR, RFC\"],\"+mFukB\":[\"Текст, который команда уже написала, получает тип и место в графе, и агент подтягивает гайд для той директории, которую правит, вместо грепа по всей папке.\"],\"+niJk2\":[\"Агент открывает\"],\"+onaNO\":[\"Ставите вы одно. Плагин работает поверх CLI, поэтому CLI идёт первым: archcore init настраивает ваших агентов и ставит плагин на выбранные хосты (Claude Code, Cursor, Codex CLI, GitHub Copilot CLI). Для любого другого MCP-агента ставить нужно только CLI.\"],\"+pqyc6\":[\"Предлагает каскад <0>adr → rule → guide</0>. Согласитесь, и он заодно сгенерирует командное правило и гайд по миграции.\"],\"+rmzWx\":[\"Пройти весь цикл\"],\"+yaNMH\":[\"Что добавляет плагин\"],\"/2sg7a\":[\"Агент читает их до того, как писать код, и делает по правилам этого репозитория, а не по тем, которые знает откуда-то ещё.\"],\"/9kPKx\":[\"«Оформите решение о базе данных из CLAUDE.md как ADR в Archcore».\"],\"/C0+pe\":[\"Зафиксируйте то, что уже живёт в коде, и агент перестанет переоткрывать одно и то же.\"],\"/FVoze\":[\"Попросите агента обычными словами или запустите slash-команду. Каждый скилл использует то, что сохранил предыдущий, а четвёртый шаг заканчивается вердиктом по каждой находке: <0>spec-wrong</0>, если устарел документ, <1>code-wrong</1>, если ветка нарушила решение, и <2>ok</2>, если они сходятся.\"],\"/NQhpT\":[\"Работаете в Gemini CLI, OpenCode, Roo Code или Cline? CLI подключает все восемь поддерживаемых агентов через MCP и хуки сессии.\"],\"/SCOAg\":[\"Вы получаете всю цепочку решений, правил и гайдов за один проход. Связи проставляются автоматически.\"],\"/hB9bv\":[\"Посмотрите, как это выглядит, ещё до установки.\"],\"/j4n+g\":[\"Выполните эти команды в папке проекта, чтобы установить Archcore и подключить агента.\"],\"0+++0P\":[\"Правки порождают расхождения: устаревшие документы, порванные связи, статусы, которые больше не совпадают с реальностью. Чем раньше вы заметите расхождение, тем дешевле его исправить.\"],\"07P+yU\":[\"Зачем здесь CLI: больше контроля — связи явные, их видно на ревью, их можно переиграть. Удобно для compliance-чувствительных задач вроде этого auth-примера.\"],\"07PsiQ\":[\"Кто поддерживает\"],\"0FV9Qx\":[\"MCP регистрируется автоматически. <0>plugin_hooks</0> — фича-флаг (по умолчанию выключен) — включите его для валидации, каскадов и инъекции контекста перед правкой.\"],\"0FbQ8U\":[\"ADR — самая компактная полезная единица контекста репозитория. Каскадните одно решение в правило и миграционный гайд, и тогда агент будет его соблюдать, а не просто помнить.\"],\"0IXro1\":[\"Один контекст проекта. Любой агент разработки.\"],\"0LxFsz\":[\"Перестаньте заново объяснять свой репозиторий каждому AI-агенту разработки.\"],\"0N3Mdn\":[\"Что вы получаете внутри агента:\"],\"0Th/L7\":[\"В Copilot плагин не поставляет MCP-сервер, поэтому шаг 2 регистрирует его на уровне проекта — без него инструментов для документов не будет вовсе. Выполните один раз на репозиторий и закоммитьте результат. Только Copilot CLI: в режиме агента VS Code самостоятельная установка плагина недоступна.\"],\"0dh83q\":[\"Разница лишь в том, видел ли он сперва ваши решения, правила и паттерны.\"],\"0gNqTq\":[\"<0>archcore init</0> создаёт <1>.archcore/</1> и подключает MCP и хуки к тем агентам, которыми вы уже пользуетесь.\"],\"0m5cr2\":[\"«Прежде чем я трону src/auth/, какие правила здесь применимы?»\"],\"0zWL3q\":[\"Агент вызывает <0>create_document(type=idea)</0> через MCP.\"],\"100w3E\":[\"Открытый код · Локальное хранение\"],\"1BxRpU\":[\"Поставить звезду CLI на GitHub\"],\"1CZ8J6\":[\"Файлы инструкций не масштабируются.\"],\"1CZCqr\":[\"Проверьте, что нужно для настройки вашего агента\"],\"1Im9rR\":[\"macOS / Linux\"],\"1PCGim\":[\"Спецификации, решения, правила, планы и знание о проекте.\"],\"1TBVNh\":[\"Если вызвать сразу после захвата, decide предложит продолжающий каскад <0>spec → rule → guide</0>.\"],\"1VAFSb\":[\"Один бинарник. Локальный MCP внутри вашего репозитория. macOS, Linux, Windows — без внешних сервисов.\"],\"1Vs9fY\":[\"Определяет масштаб и форму репозитория и собирает полный стартовый набор: правило стека, гайд по запуску, модель данных, точки входа и спеки для самых горячих модулей.\"],\"1fve4d\":[\"Ваш код лежит в Git. Понимание проекта должно лежать там же.\"],\"1g++4u\":[\"Между этими четырьмя шагами команды вводить не нужно. Там, где есть поддержка хуков, агент получает спецификацию и ADR во время правок, а в начале сессии — сводку принятых решений и текущей работы. В остальных средах те же документы доступны через MCP.\"],\"1ofM+e\":[\"Сохраните инструкции, которыми уже пользуетесь\"],\"1wkhP0\":[\"Codex CLI 0.117+\"],\"2/svZk\":[\"Решайте задачи с уже существующим контекстом\"],\"22HRS4\":[\"Spec-driven разработка\"],\"25CLfa\":[\"Распознаёт это как решение и запускает трек решений — готовит <0>use-postgres.adr.md</0> со статусом, контекстом, решением и последствиями.\"],\"25vaI7\":[\"Spec-driven разработка и context engineering для AI-агентов. Храните спецификации, архитектуру, решения, правила и планы вместе с кодом в Git.\"],\"28JysL\":[\"Archcore CLI\"],\"2CeNK+\":[\"Какие команды у плагина?\"],\"2DvxN2\":[\"Зачем нужен плагин\"],\"2Ig1mK\":[\"Опишите задачу обычным языком — Archcore сам направит её куда нужно. Команды <0>/archcore:*</0> ниже — это просто шорткаты к тем же сценариям.\"],\"2Jlbm1\":[\"Каждая начинается с фразы, которую вы говорите агенту. В Claude Code, Cursor, Codex CLI и Copilot то же самое делает slash-команда, она указана под фразой.\"],\"2LxK9d\":[\"Контекст проекта\"],\"2NX5hu\":[\"Файл в диффе: решение проходит ревью наравне с кодом, который на нём держится.\"],\"2RpOxX\":[\"Зачем здесь CLI: больше контроля. Вы сами решаете, насколько дробить фазы и какие ставить связи. Можно заскриптовать генерацию планов по пачке спек.\"],\"2TIzbZ\":[\"Вызов <0>list_relations</0> у агента вернёт связи, которые вы прописали.\"],\"2WQmIH\":[\"Контекстная инженерия\"],\"2WS8Ka\":[\"Заново изобретает соглашения, уже принятые командой\"],\"2b1Hah\":[\"Каждая задача ниже начинается с фразы, которую вы говорите агенту. В Claude Code, Cursor, Codex CLI и Copilot то же самое делает slash-команда, она указана под фразой.\"],\"2gKBhJ\":[\"Методологические инструменты описывают процесс разработки. Archcore сохраняет получившееся знание о проекте живым, связанным, версионированным и доступным агентам на всём протяжении реализации. Спецификация — часть этого контекста, но не весь контекст. <0>Spec-driven разработка для AI-агентов</0>.\"],\"2hDGxH\":[\"У модуля есть знание в головах, но нет документа\"],\"2tz4mE\":[\"<0>archcore status</0> печатает полное дерево документов со статусами.\"],\"2vVR4f\":[\"Star\"],\"2yT2Ov\":[\"Превратите спеку в правило + гайд.\"],\"2z1zGB\":[\"Источник и проверка ↗\"],\"313SY1\":[\"Пройти заново\"],\"39jxvW\":[\"Между планированием и слиянием ничего не приходится объяснять заново. Спецификация, которая задала объём фичи, — та самая, с которой ревью сверяет вашу ветку и с которой начинается следующий план.\"],\"3CKceo\":[\"Всё пишется в <0>.archcore/</0> обычным markdown. Вы смотрите диф как в любом коммите. То же подтверждение настраивает конфиги хостов, поэтому коллеги на одном лишь CLI тоже всё получат.\"],\"3H7XP4\":[\"Windows\"],\"3IEFwy\":[\"Нет. Плагин и CLI работают полностью локально — без аккаунтов, телеметрии и внешних сервисов. .archcore/ — это обычный markdown, версионируемый в вашем Git-репозитории.\"],\"3JXXVi\":[\"Создайте файл <0>.env</0>\"],\"3aukOs\":[\"Цикл замкнут: загрузили контекст, поменяли код, провели аудит. Следующая победа — сделать это автоматической частью повседневного флоу.\"],\"3eqAav\":[\"К списку путей\"],\"3gRgZL\":[\"Подгружается через локальный MCP ещё до правок\"],\"3rl3/o\":[\"Решения остаются в чате\"],\"3vvx/h\":[\"Восемь агентов, одна директория .archcore/.\"],\"40X6c9\":[\"Реализовано\"],\"4A1lWo\":[\"Базовый слой контекста для любого MCP-агента — Copilot, Gemini CLI, OpenCode, Cline. Один бинарник, скриптуется в CI.\"],\"4EYsZX\":[\"Плагин или CLI?\"],\"4IKt6E\":[\"Контекст подгружается в начале сессии\"],\"4Xlfw6\":[\"Загрузите нужный контекст до правок.\"],\"4brcWc\":[\"Каждый день, перед правками\"],\"4eLzWp\":[\"Claude Code (production), а также Cursor 2.5+, Codex CLI 0.117+ и GitHub Copilot CLI (реализовано). В Copilot нужно дополнительно выполнить archcore init --agent copilot один раз на репозиторий — туда плагин не поставляет MCP-сервер. Для других агентов с MCP используйте CLI напрямую.\"],\"4jQXMi\":[\"Archcore меряет объём по тому, что работа реально задевает, и мелкое остаётся мелким.\"],\"4lS2Is\":[\"Зафиксируйте решение: используем PostgreSQL как основную базу.\"],\"4rpLrT\":[\"Запустите это в репозитории, с которым собираетесь работать. Он найдёт агентов, которые у вас уже стоят, и подключит их.\"],\"4zKLAd\":[\"Спеки описывают, что система должна делать — интерфейсы, инварианты, краевые случаи. Они стоят между PRD («зачем») и планами («как»).\"],\"5+awtj\":[\"С Archcore\"],\"50Z64p\":[\"Зачем здесь CLI: больше контроля — эти запросы прямо встают в GitHub Actions или pre-commit-хуки. Шаг аудита становится настоящим гейтом мёрджа.\"],\"55/iWE\":[\"Запускайте перед мержем всего, что затрагивает документированный код. На основной ветке или при пустом дифе вместо этого выводится сводка о здоровье проекта.\"],\"5B85ww\":[\"Готовит спеку на основе PRD; вы принимаете и переходите к шагу плана.\"],\"5J997S\":[\"Выберите модуль для захвата.\"],\"5K9ea5\":[\"Об этой интеграции\"],\"5N03BH\":[\"Все пути\"],\"5ReKpW\":[\"Перед мержем; --drift и --deep для аудита\"],\"5XY1Q7\":[\"Git-нативный слой контекста\"],\"5aF3AK\":[\"После установки откройте новое окно PowerShell, чтобы PATH обновился. Затем выполните <0>archcore init</0> в корне репозитория.\"],\"5c6q+J\":[\"Запишите ADR или RFC. При необходимости закрепите его как правило команды для будущих правок в той же области. Или опишите модуль, который пока знает только его автор.\"],\"5dOoOd\":[\"Зачем здесь CLI: больше контроля. Каждый связанный документ проходит через один явный вызов MCP. Это можно заскриптовать и подсовывать нужный контекст любому своему агенту в начале сессии.\"],\"5dTdbz\":[\"MCP и хуки. Проверьте версию Codex, отметьте проект как доверенный и разрешите хуки, прежде чем рассчитывать на их работу.\"],\"5f+Kcq\":[\"Скопировать инструкции\"],\"5i1AdV\":[\"Какое первое действие даст результат быстрее всего?\"],\"5jbVog\":[\"Методологические инструменты описывают процесс разработки. Archcore сохраняет получившееся знание о проекте живым, связанным, версионированным и доступным агентам на всём протяжении реализации. Спецификация — часть этого контекста, но не весь контекст: она живёт рядом с архитектурой, прежними решениями, ограничениями и правилами команды, которые агенту тоже нужны. <0>Spec-driven разработка для AI-агентов</0>.\"],\"5kGvNY\":[\"Граф связей уже соединил их между собой.\"],\"5lBhug\":[\"Пройдёт по каждому документу, сверит поле статуса с датой последней правки и отметит рассинхрон.\"],\"5s4xky\":[\"Распознаёт стек и предлагает правило для стека.\"],\"5vtp0g\":[\"Читает спецификацию из шага 2 и решение из шага 3. Вердикт по каждой находке: <0>spec-wrong</0>, <1>code-wrong</1> или <2>ok</2>.\"],\"5wyKtM\":[\"MCP и хуки сессии.\"],\"610SxU\":[\"Связи прописываются автоматически — правило <0>implements</0> спеку, гайд <1>related</1> правилу.\"],\"61ymub\":[\"Поставить звезду CLI на GitHub\"],\"66Xtyx\":[\"Зачем здесь CLI: status — одна шелл-команда, без похода к агенту. Удобно для pre-commit-хуков или PR-проверок.\"],\"67hj67\":[\"Прописывает <0>add_relation(plan implements spec)</0>.\"],\"6B/wwg\":[\"Зачем здесь CLI: больше контроля — вы выбираете тип явно, не полагаясь на эвристику плагина. Полезно, когда модуль ближе к «doc» или «guide», чем к «spec».\"],\"6BDqha\":[\"Ограничения\"],\"6JUP4n\":[\"Проверка здоровья документации\"],\"6PzCY8\":[\"Агент получает их, не спрашивая. А каждая сессия начинается со сводки: что уже решено и что в работе.\"],\"6Wedvr\":[\"Подключите агентов, которыми пользуется ваша команда\"],\"6a4Bso\":[\"Сделать репозиторий понятным для AI-агентов\"],\"6oHkze\":[\"Трек <0>feature</0> вставляет остановку <1>.spec.md</1> между PRD и планом.\"],\"6ooqiw\":[\"Одна команда превращает репозиторий в структурированный контекст.\"],\"6op9v0\":[\"Всё пишется в <0>.archcore/</0> обычным markdown — diff смотрите как любой другой коммит.\"],\"6qcirv\":[\"Источник и проверка\"],\"6wXOML\":[\"Теперь у вас есть вся цепочка (idea, PRD, spec, plan), связанная воедино. Следующая сессия, которая откроет любой из них, подтянет остальные.\"],\"6z9W13\":[\"Сначала\"],\"6ziaDx\":[\"Плагин сначала обходит тему как поисковый запрос, потом пишет спеку. Точно так же работает для «auth flow», «биллинга», «job экспорта отчётов».\"],\"70/l+y\":[\"Да. Перед запуском агента добавьте выбранный бинарный файл archcore в PATH. Можно использовать готовый релиз или сборку из исходников.\"],\"77pnR0\":[\"Спецификации, решения, правила и планы лежат в <0>.archcore/</0> обычным Markdown и версионируются вместе с кодом, который описывают. Изменение правила приходит диффом, который кто-то утверждает.\"],\"79hK7Y\":[\"Опишите пайплайн, а не путь:\"],\"7BN/5R\":[\"Claude Code, Cursor и Codex CLI выдают код, который игнорирует ваши соглашения, ADR и ранее принятые решения.\"],\"7SkgtC\":[\"With the instructions\"],\"7XlLJY\":[\"Claude Code (production), а также Cursor 2.5+, Codex CLI 0.117+ и GitHub Copilot CLI (реализовано). В Copilot нужно дополнительно выполнить archcore init --agent copilot один раз на репозиторий, потому что туда плагин не поставляет MCP-сервер. Для других агентов с MCP используйте CLI напрямую.\"],\"7Zrus7\":[\"Подтягивает <0>billing-format.spec.md</0>.\"],\"7Zwoqc\":[\"Скажите фразу или наберите ярлык. Фраза работает в любом агенте, который умеет MCP; ярлык делает то же самое в Claude Code, Cursor, Codex CLI и Copilot.\"],\"7jQ5vd\":[\"Документы проекта хранятся в вашем репозитории. Аккаунт и облачный сервер не нужны.\"],\"7l15X4\":[\"не пройдено\"],\"7nwW0T\":[\"Нужны ли мне одновременно плагин и CLI?\"],\"7oSRbV\":[\"Документы, которые ваша правка только что сделала неверными, если добавить <0>--drift</0>.\"],\"7rKIWx\":[\"В каталоге .archcore/ вашего репозитория, в формате Markdown с метаданными YAML. Вы проверяете и коммитите их вместе с кодом. Передача контекста модели регулируется настройками провайдера вашего агента.\"],\"7rkoGE\":[\"Четыре slash-команды. Повседневному контексту не нужна ни одна из них.\"],\"7tnXib\":[\"Ещё и хост плагина\"],\"7z/Jp/\":[\"Запустите внутри агента:\"],\"8+STJJ\":[\"Проверка сверяет вашу ветку со спецификацией и записью решения и возвращает <0>code-wrong</0> на файл, который их проигнорировал.\"],\"80TxEA\":[\"Без команд. Просто попросите внести правку:\"],\"81jE5H\":[\"Затем <0>add_relation(spec implements prd)</0>.\"],\"89Z+U5\":[\"Claude Code, Cursor, Codex CLI, GitHub Copilot, Gemini CLI, OpenCode, Roo Code и Cline. Slash-команды, скиллы и защитные проверки работают внутри первых четырёх, остальные получают те же документы через MCP. Если среда поддерживает хуки, документы приходят до правки, без единой команды с вашей стороны.\"],\"8AULTO\":[\"Как это работает\"],\"8AdMB8\":[\"Впервые в Archcore? Пройдите тур за 5 минут.\"],\"8DjbCe\":[\"ADR в <0>.archcore/db/use-postgres.adr.md</0>: там и вердикт, и рассуждение, которое к нему привело.\"],\"8FCryp\":[\"Можно ли использовать свою установку CLI?\"],\"8LfxeG\":[\"Гайды, спеки и планы\"],\"8OBrPE\":[\"Всё остальное, что говорит на MCP, работает так же: CLI — это локальный MCP-сервер, а не отдельная интеграция под каждого вендора.\"],\"8P7coo\":[\"Изменение правила — это диф, который кто-то апрувит.\"],\"8Zzf5Q\":[\"Документация CLI\"],\"8actCd\":[\"Предлагает документы по архитектуре, правилам и ключевым модулям. Ничего не сохраняется без вашего подтверждения.\"],\"8bSToo\":[\"Пишет спецификацию того, как должен вести себя rate limiting, и план, который разбивает работу на задачи.\"],\"8cJeWi\":[\"Берёт первую попавшуюся знакомую библиотеку\"],\"8ga4s4\":[\"Подключите своих агентов\"],\"8ieX7k\":[\"Почему контексту проекта место в Git\"],\"8jTfgv\":[\"Нет. Плагин работает поверх CLI, поэтому вместе с плагином вы получаете и то и другое. Нужен только базовый слой контекста? Ставьте CLI отдельно.\"],\"8kVcO8\":[\"Работает с Claude Code · Cursor · Codex CLI · Copilot · Gemini CLI · любым MCP-агентом\"],\"8kuopi\":[\"Зачем здесь CLI: больше контроля — повесьте это в pre-merge CI-шаг, и рассинхрон уже не проскочит мимо ревью.\"],\"8mO1uM\":[\"Восемь через MCP: Claude Code, Cursor, Gemini CLI, GitHub Copilot, OpenCode, Codex CLI, Roo Code и Cline (ручная настройка). Пятеро из них получают ещё и хуки сессии: Claude Code, Cursor, Gemini CLI, Codex CLI и GitHub Copilot. Выполните archcore mcp install или archcore hooks install, чтобы подключить каждого.\"],\"8myVyZ\":[\"Шесть задач, ради которых его запускают.\"],\"8tpgqB\":[\"Решение принято\"],\"8uA5Jn\":[\"Ярлык\"],\"8w2vd4\":[\"<0>use-postgres.adr.md</0>, решение, которое наследуют ваши запросы.\"],\"8w5rjE\":[\"Claude Code\"],\"96Fbz5\":[\"Трек <0>sdd</0> идёт idea → PRD → spec → plan. Укажите <1>sources</1> для исследования рынка (MRD → BRD → URD) или <2>iso</2> для каскада по ISO 29148.\"],\"9AhqBi\":[\"Подписаться на обновления\"],\"9BUr0j\":[\"Маркетплейс плагинов\"],\"9ExMcS\":[\"Положите туда что-нибудь\"],\"9I9QiT\":[\"Если среда поддерживает хуки перед записью, нужные правила и спецификации поступают до правок. Хуки сессии дают сводку принятых решений и текущей работы. Поддержка для каждой среды указана на странице CLI.\"],\"9J+SPe\":[\"Если среда поддерживает хуки перед записью, Archcore передаёт документы с требованиями к файлу до того, как агент его изменит. Остальные MCP-агенты могут находить и читать те же документы во время работы.\"],\"9TNz2n\":[\"Изучите репозиторий и создайте начальные документы проекта.\"],\"9kwAHz\":[\"Используйте Archcore вместе с инструментами, которые у вас уже есть, или сделайте его частью своей оболочки агента.\"],\"9qyRUV\":[\"Версия инструкций\"],\"9u/nMf\":[\"Плагину нужен хост с рантаймом плагинов. Любой другой MCP-агент читает ту же директорию .archcore/ через CLI — тот же источник правды, другая точка входа.\"],\"9u51aN\":[\"Зафиксировать решение или описать то, что живёт в коде\"],\"9uijLN\":[\"Да, одна глобальная установка. Выполните curl -fsSL https://archcore.ai/install.sh | bash (или эквивалент в PowerShell на Windows), затем добавьте плагин. MCP запускает archcore из вашего PATH.\"],\"9vNj0E\":[\"Какие агенты поддерживаются?\"],\"9zWQ2f\":[\"Спросите у агента:\"],\"A5O5uO\":[\"Нарушенное решение находится до слияния\"],\"AEMVhB\":[\"Начните с Archcore.\"],\"AFkUik\":[\"Один конфиг — все агенты\"],\"AJ7IVo\":[\"Четыре шага на одной фиче, от пустого репозитория до смерженной ветки. Скажите фразу или наберите ярлык, разницы нет.\"],\"AKgabO\":[\"Определите объём новой функции или рефакторинга до начала работы.\"],\"ASNpSX\":[\"Задачи\"],\"AW2rsm\":[\"Читает спецификацию из шага 2 и решение из шага 3, затем выносит вердикт по каждой находке.\"],\"AZkteM\":[\"Archcore — open source, разрабатывается публично. Звезда помогает другим разработчикам его найти и подсказывает нам, куда двигаться дальше.\"],\"Ac/uUs\":[\"Предлагает каскад <0>adr → rule → guide</0> — примите, чтобы заодно получить командное правило и миграционный гайд.\"],\"AdG++1\":[\"Как установить\"],\"Ai2U7L\":[\"Хост\"],\"Allvml\":[\"Спецификации и правила, которые касаются файла, доходят до агента прямо во время правки.\"],\"AvYbUL\":[\"Поставить звезду на GitHub\"],\"Aw6j4B\":[\"Открыть тур\"],\"AyVDiM\":[\"Короткий интерактивный разбор: когда брать плагин, когда CLI и как подключить контекст к вашему AI-агенту, за 3-5 шагов.\"],\"B02Hra\":[\"Спорите один раз, записываете, к чему пришли, и через три месяца не начинаете заново.\"],\"BAdbMw\":[\"Каждый агент видит свою версию проекта.\"],\"BB+cET\":[\"Предложение продолжить: командное правило, которое следует из решения, и гайд по миграции.\"],\"BDAljf\":[\"<0>\",[\"importCommand\"],\"</0> импортирует файлы инструкций, которые вы уже написали — CLAUDE.md, AGENTS.md, .cursorrules, .cursor/rules/* — как типизированные документы. Написанный вами контекст переносится; он просто перестаёт быть одним плоским файлом на инструмент.\"],\"BEN2uG\":[\"Как пользоваться Archcore\"],\"BFV0qD\":[\"Зачем здесь CLI: больше контроля — вы сами выбираете типы связей (related / depends_on и т.д.), а не принимаете дефолты плагина.\"],\"BHJ5v+\":[\"Следующая задача начнётся с уже сохранённого контекста. Спецификации и решения остаются в Git рядом с кодом.\"],\"BITFnQ\":[\"Правки порождают рассинхрон — устаревшие документы, обрывы связей, статусы, оторванные от реальности. Чем раньше его заметите — тем дешевле исправить.\"],\"BL5Yxq\":[\"Описать существующий код\"],\"BMlGC6\":[\"Версионированные правила в Git\"],\"BMxg3P\":[\"Запросите следующий документ, когда будете готовы. Каскадом управляете вы, по одному вызову за раз.\"],\"Bi+Y/1\":[\"Спросите агента:\"],\"Bz9/w9\":[\"Проверьте параметр hooks в настройках Codex. MCP и навыки работают независимо от хуков.\"],\"CEtEAH\":[\"Разработка по спецификациям после слияния кода\"],\"CIiJoT\":[\"Не лучше ли установить плагин?\"],\"CPMS+c\":[\"Код, соответствующий вашей архитектуре с первого раза.\"],\"CRVHyp\":[\"Добавьте spec-driven разработку и автоматический контекст проекта в Claude Code, Cursor, Codex CLI и GitHub Copilot CLI с помощью Archcore.\"],\"CTKeFK\":[\"Поднимает ADR: «Rate limiting через Redis token bucket»\"],\"CXWQUv\":[\"Запишите ADR или RFC и при желании закрепите его командным правилом, которое само применяется ко всем будущим правкам в этой области. Или опишите модуль, который существует только в чьей-то голове.\"],\"Ca4xcX\":[\"Связь <0>implements</0> ставится явным вызовом MCP: посмотрите и подтвердите.\"],\"CcyGAn\":[\"Скажите агенту, что вам нужно.<0/>Archcore это запишет.\"],\"Ch8NIs\":[\"Как пользоваться Archcore: один цикл от init до review\"],\"CkBQAK\":[\"автоматически\"],\"Cric8h\":[\"Что он должен делать\"],\"CwdHhe\":[\"Ваш агент забывает правила в каждой сессии.\"],\"D+c24u\":[\"Сверьте ветку с записанными правилами и решениями в обе стороны: код, который сломал документ, и документы, от которых код ушёл вперёд.\"],\"D0mGRv\":[\"Нет подстановки контекста перед записью\"],\"DB8zMK\":[\"Применить\"],\"DCxw9t\":[\"Полезные следующие запросы:\"],\"DFY4fD\":[\"Готовит черновик <0>how-to-run.guide.md</0> на основе ваших скриптов.\"],\"DM7mR/\":[\"Файлы инструкций, привязанные к путям, сохраняют свою область действия, но получают статус, даты и связи — видно, что ещё в силе, а что перекрыто более поздним решением.\"],\"DP0igd\":[\"codex plugin marketplace add\"],\"DV2fHm\":[\"Готовит спеку, которая описывает контракт, а не реализацию.\"],\"Da17cA\":[\"Каких AI-агентов поддерживает CLI?\"],\"DaNtIb\":[\"пример структуры\"],\"DciM2L\":[\"Git-нативность\"],\"DdArJf\":[\"Всё лежит в папке <0>.archcore/</0> внутри вашего репозитория. Обычный Markdown: без базы данных и внешних сервисов.\"],\"DpNfu6\":[\"Скилл задаёт порядок действий агента для конкретной задачи. Здесь четыре скилла помогают добавить ограничение частоты запросов к публичному API: сколько раз клиент может к нему обратиться.\"],\"Dpz8Pa\":[\"Четвёртый шаг заканчивается вердиктом по каждой находке: <0>spec-wrong</0>, если устарел документ, <1>code-wrong</1>, если ветка нарушила решение, и <2>ok</2>, если они сходятся.\"],\"DrpFjc\":[\"Решение, которое уже выбрало хранилище.\"],\"DxbI6N\":[\"У экспериментальных интеграций есть инструкции по настройке. Совместные прогоны пока не проверены.\"],\"E56OWW\":[\"Разверните полный стек Archcore Team с помощью Docker Compose за 3 шага.\"],\"E6/Ij8\":[\"Найти устаревшие, отсутствующие или расходящиеся с кодом доки\"],\"E7XxXR\":[\"Зачем здесь CLI: больше контроля — эти запросы складываются в одну CI-задачу, которая аудитит покрытие на каждом пуше.\"],\"EDpXqt\":[\"Потом попросите агента связать их: <0>add_relation(rule implements adr)</0>, <1>add_relation(guide related rule)</1>.\"],\"EEh8zY\":[\"Хук сессии плагина теперь сам подмешает эти документы в следующий раз, когда вы тронете что-то, на что они распространяются.\"],\"EIwsH5\":[\"Каскад останавливается на каждом шаге. Вы можете поправить черновик в редакторе, прежде чем принять его и идти дальше.\"],\"EJdonM\":[\"Четыре: /archcore:init (первичная настройка), /archcore:plan (от идеи до проработанного плана), /archcore:document (зафиксировать решение или описать существующий код) и /archcore:review (сверить изменения и документацию). Повседневный контекст не требует команд — хуки подставляют нужные правила и спеки во время правок.\"],\"ELciF6\":[\"Посмотреть, как это работает\"],\"EQ3F4N\":[\"Игнорирует Redis, который вы уже используете\"],\"ESQKO8\":[\"Полная матрица хостов\"],\"ESR/CK\":[\"Ставить нужно одно, настраивать после этого нечего. Каждый пример на странице — фраза, которую вы можете сказать агенту прямо сегодня.\"],\"EbOeZu\":[\"Что добавляет плагин?\"],\"EhbaSA\":[\"Зачем здесь CLI: больше контроля. Вы решаете, когда и стоит ли вообще переходить к PRD. Полезно, когда идея ещё может умереть в обсуждении.\"],\"EjA9GG\":[\"Спрашивает подтверждение перед записью. Вы можете сменить тип или сначала поправить черновик.\"],\"EkuGXf\":[\"Трек feature уместен, когда есть реальный API или схема, которые нужно зафиксировать. На стадии ideation его пропускайте.\"],\"EpzkTT\":[\"Файлы инструкций дают плоскую память: один инструмент, один файл. У Archcore есть структура. Он хранит типизированные документы (ADR, rule, plan, guide, spec) со связями и историей версий, которые читаются и пишутся во время реальной работы и переиспользуются каждым агентом.\"],\"EtKoce\":[\"Документация плагина\"],\"EuHsS9\":[\"CLAUDE.md (190 строк, и растёт)\"],\"EufvBx\":[\"Результат\"],\"F0xP2N\":[\"Cursor 2.5+\"],\"F6Myi3\":[\"Archcore сверяет ваш дифф с документами, которые берутся его описывать.\"],\"F7G/TS\":[\"Часто задаваемые вопросы\"],\"FAz920\":[\"Проверьте, что получилось.\"],\"FFxWjm\":[\"Затем <0>list_documents</0> + <1>list_relations</1>, чтобы пройтись по графу.\"],\"FIsB3G\":[\"Принято решение или у модуля нет документации\"],\"FJv2fl\":[\"Правка вёрстки: ни одного документа.\"],\"FQB6/x\":[\"Это раздует контекстное окно агента?\"],\"FQVyhU\":[\"MCP регистрируется автоматически. Доступность хуков зависит от установленной версии Codex и параметра hooks.\"],\"FSBV7H\":[\"Зачем здесь CLI: больше контроля. Вы задаёте тип явно, а не полагаетесь на эвристику плагина. Полезно, когда модулю больше подходит «doc» или «guide», чем «spec».\"],\"FUmqzz\":[\"Чем это отличается от CLAUDE.md или AGENTS.md?\"],\"FiIln6\":[\"Каскад замирает на каждом гейте — черновик можно поправить в редакторе, потом принять и двигаться дальше.\"],\"FiXCsC\":[\"Плагин Archcore добавляет агенту навыки планирования, документирования и проверки изменений. Он работает через CLI с документами вашего проекта.\"],\"FnJjCu\":[\"Или сделайте Archcore частью своей оболочки\"],\"G/kVeS\":[\"Решения растворяются в истории чата.\"],\"G1lFHS\":[\"Четыре slash-команды — а повседневный контекст не требует ни одной.\"],\"G5PFd6\":[\"Спецификации, которые не отрываются от реализации\"],\"GC/du7\":[\"Проектирование того, что агенту сообщают до действия и что проверяет его после, называется harness engineering. Ваш агент приносит цикл, инструменты и песочницу. Archcore держит ту половину, которую вам не привезёт ни один вендор: что ваш проект решил, что требует и что запрещает. <0>Разбор harness engineering</0>.\"],\"GElrjf\":[\"Какой агент вы используете?\"],\"GJ5dwy\":[\"PRD отвечает на вопросы «почему сейчас» и «как мы поймём, что сработало». Идея их сознательно пропускает. Агент читает идею и спрашивает только то, чего не хватает.\"],\"GLHcF9\":[\"Как Archcore хранит данные проекта и собирает аналитику установки, обновлений и сайта. Передача данных провайдерам моделей и отключение аналитики.\"],\"GMYqDn\":[\"Инструкции просят агента:\"],\"GQST6l\":[\"Соглашение, которому следует ответ.\"],\"GQUraY\":[\"Claude Code, Cursor 2.5+, Codex CLI 0.117+ и GitHub Copilot CLI. В Cursor нужно зарегистрировать MCP, а в Copilot настроить подключение для проекта. Различия описаны в таблице выше.\"],\"GSr0rF\":[\"Открыть меню\"],\"GWvHXw\":[\"Все шесть задач и первые пятнадцать минут\"],\"GdGiNi\":[\"Шаг \",[\"current\"],\" из \",[\"total\"]],\"Gp7xEe\":[\"Установите CLI, затем выполните archcore init в папке проекта.\"],\"GpQtUK\":[\"Любой агент читает одну и ту же папку\"],\"Gs5KD1\":[\"Все 7 команд одним взглядом\"],\"H5BXo3\":[\"Нет. archcore init импортирует существующие файлы инструкций — CLAUDE.md, AGENTS.md, .cursorrules, .cursor/rules/* — как структурированные документы, так что уже написанный контекст переносится.\"],\"H5IdfC\":[\"Типизированные решения (ADR)\"],\"H7qMZD\":[\"<0>init</0> сам находит установленных агентов (Claude Code, Cursor, Copilot, Gemini CLI…) и прописывает MCP и хуки для каждого. Идемпотентно, повторный запуск безопасен.\"],\"H8xrxC\":[\"Где работает плагин\"],\"HKt6X5\":[\"Claude Code, Cursor, Codex? Смотрите плагин\"],\"HLgT9d\":[\"Агент не понял вопрос? Запустите <0>archcore doctor</0>. Он за один проход покажет регистрацию MCP, установку хуков и порядок в тегах.\"],\"HU3Fgo\":[\"Для этой версии инструкций совместных прогонов не записано.\"],\"HWD3Hk\":[\"copilot plugin install + archcore init\"],\"Hf1cmv\":[\"Зачем здесь CLI: больше контроля — границы и исключения спеки задаёте сами, а не принимаете то, что предложил бы плагин.\"],\"HhQKIc\":[\"Смотреть пользу и ограничения →\"],\"HhbhE8\":[\"Базовый слой контекста для любого агента с MCP — Gemini CLI, OpenCode, Roo Code, Cline. Один бинарник, скриптуется в CI.\"],\"Hk0wPE\":[\"Зачем здесь CLI: больше контроля. Эти запросы складываются в одну CI-задачу, которая проверяет покрытие на каждый пуш.\"],\"I+s1F8\":[\"В GitHub Copilot CLI плагин не может нести собственный MCP-сервер, поэтому однократная настройка проекта через <0>archcore init --agent copilot</0> обязательна, а не опциональна. Без неё инструментов для документов не будет.\"],\"I3wYEy\":[\"MCP и хуки. Проверьте параметр hooks в установленной версии Codex.\"],\"I7VWEc\":[\"Как это будет сделано\"],\"I8EMiv\":[\"Выполните archcore init --agent copilot в каждом проекте, чтобы подключить MCP. Режим агента в VS Code не загружает этот плагин.\"],\"IKrRiW\":[\"Спроектированный контекст этим и отличается от длинного промпта: он явный, структурированный, выборочный, версионированный и переносимый между агентами.\"],\"IL1Dhw\":[\"Раздел Plugins → вставить URL.\"],\"IRhwNA\":[\"Документы проекта, которые можно проверить в Git\"],\"IToAXJ\":[\"Продолжите каскад:\"],\"IVHQQ5\":[\"Явный запрос типа отключает эвристику агента. Тип результата становится предсказуемым.\"],\"Ij1hNl\":[\"Зачем здесь CLI: больше контроля — вы сами решаете гранулярность фаз и связи. Можно собрать скрипт, который генерирует планы из пачки спек.\"],\"IllC38\":[\"Спланировать фичу до того, как её начнут писать\"],\"IoK6rt\":[\"Новая фича, рефакторинг или инициатива\"],\"Iqh0Uv\":[\"В планах\"],\"IxqQAH\":[\"Ставить нужно одно, настраивать после этого нечего.\"],\"J+8dhC\":[\"Как использовать\"],\"J+X/xd\":[\"Ваш дифф сверяется со спецификацией из шага 2 и ADR из шага 3, в обе стороны: код, который разъехался, и документы, которые правка сделала неверными.\"],\"JEDmqY\":[\"Контексту проекта место в Git\"],\"JKK26q\":[\"Один бинарь, локальный MCP в репозитории — macOS, Linux, Windows.\"],\"JdOpYJ\":[\"Доступно из любых агентов\"],\"Jhjjpz\":[\"Базовый слой контекста для любого агента с MCP: Gemini CLI, OpenCode, Roo Code, Cline. Один бинарник, скриптуется в CI.\"],\"JmZ/+d\":[\"Готово\"],\"Jwmj5X\":[\"Репозиторий плагина\"],\"K3i7ii\":[\"<0>Контекстная инженерия для AI-агентов разработки</0> разбирает все пять свойств подробно, с разобранными примерами.\"],\"K4CY/o\":[\"Находит поддерживаемых агентов и выбирает правильный путь интеграции.\"],\"K4Whj4\":[\"Проверить ветку до мержа\"],\"K7tIrx\":[\"Категория\"],\"KFeyUv\":[\"Вы снова объясняете те же правила. Опять.\"],\"KK7Qub\":[\"Создайте файл <0>docker-compose.yml</0>\"],\"KK9fY+\":[\"Решение, которое уже выбрало Redis, и правило про формат ошибок в <0>src/api/</0> доходят до агента раньше, чем он правит файл.\"],\"KPJp4R\":[\"Агент находит каждый затронутый файл (отправитель, очередь ретраев, подпись, получатели).\"],\"KQP4Jy\":[\"Заведите первый кусок структурированного контекста: правило стека, гайд по запуску или первое решение, чтобы агенту было что читать.\"],\"KQrOjA\":[\"Инициатива размером с платформу: зонтичный PRD и по спецификации на каждую возможность.\"],\"KXX3dX\":[\"Запишите реальное решение.\"],\"KcQmHI\":[\"Вы решаете, какие находки тянут на <0>update_document</0>, <1>remove_relation</1> или смену статуса.\"],\"Kcn9nb\":[\"Спецификации превращаются в устаревшие артефакты передачи.\"],\"KhSCF+\":[\"Нужный контекст подгружается, пока агенты работают.\"],\"KjJspu\":[\"Одна настройка обслуживает любого агента, который умеет в MCP.\"],\"Klktzv\":[\"Один бинарник и локальный MCP-сервер для всех остальных агентов и для CI.\"],\"KsCGY2\":[\"Плагин выбирает тип документа по тому, что прочитал. Подтвердите, и файл окажется в <0>.archcore/</0> и пойдёт на ревью.\"],\"KuyVn+\":[\"Читает папку, сам выбирает <0>type=spec</0>.\"],\"Kz1TxG\":[\"открыт\"],\"L1F6EQ\":[\"<0>archcore init</0> — одна команда, четыре вещи подключены за вас.\"],\"L4PRjM\":[\"Archcore — Git-нативный слой контекста для AI-агентов разработки.\"],\"L8/bQ4\":[\"CLI в действии\"],\"L8Fv4v\":[\"Спросите агента обычными словами:\"],\"LARPBy\":[\"Показывает всё это одним превью. До вашего единственного подтверждения ничего не пишется.\"],\"LEXiAr\":[\"Размер вы не выбираете. Archcore считает его сам и называет одной строкой до того, как что-то создаст.\"],\"LIc33M\":[\"Один цикл Archcore на живой фиче: init, plan, document, review. На каждом шаге показаны фраза, которую вы говорите агенту, и slash-команда, делающая то же самое.\"],\"LW1l0H\":[\"Агент использует MCP <0>search_documents</0> + <1>create_document(type=spec)</1>.\"],\"LW6HOH\":[\"Что делает CLI\"],\"LXFcEZ\":[\"В Codex выполните <0>/plugins</0>, откройте Archcore и выберите Install plugin. MCP регистрируется автоматически. Хуки в Codex экспериментальные — включите их через <1>codex --enable hooks</1>; на Windows они не работают.\"],\"LXsEaK\":[\"Память репозитория<0/>для любого AI-агента разработки.\"],\"Lazzll\":[\"Переносимый\"],\"LjgV7L\":[\"В <0>.archcore/</0> появляется ADR, он версионируется вместе с кодом и виден в пул-реквесте. Все следующие сессии его читают, в каком бы агенте вы их ни открыли.\"],\"LksuCE\":[\"PRD, roadmap\"],\"Ll/VrB\":[\"Вот, собственно, и всё. Выберите другой путь или сразу переходите к командам установки.\"],\"Ls9OHz\":[\"Запишите ADR или RFC и при желании закрепите его командным правилом, которое само применяется ко всем будущим правкам в этой области, — или опишите модуль, который существует только в чьей-то голове.\"],\"LsuUUs\":[\"Первые пятнадцать минут, а дальше шесть задач, ради которых его правда запускают. Каждая — фраза, которую вы говорите агенту, и файл, который после неё остаётся.\"],\"LuXg4P\":[\"Связанные артефакты собираются в единый контекст проекта.\"],\"LxcRMl\":[\"Нет. Плагин и CLI работают полностью локально: без аккаунтов, без телеметрии, без внешних сервисов. .archcore/ хранится обычным markdown в вашем Git-репозитории.\"],\"Lz8/eS\":[\"Одна фича, от начала до мержа.\"],\"M1xPhB\":[\"Archcore CLI — Git-нативный контекст для AI-агентов разработки\"],\"MDdX/4\":[\"Bash: одна строка с curl.\"],\"MDkJmD\":[\"Плагину нужен хост со средой плагинов. Любой другой агент с MCP читает тот же каталог .archcore/ через CLI: источник правды один, точка входа разная.\"],\"MHBXEL\":[\"Нужны оба шага:\"],\"MI3oYz\":[\"Поставить звезду плагину на GitHub\"],\"MJiSmM\":[\"Что нужно командам\"],\"MPEFN9\":[\"Каналы сообщества\"],\"MQfpNT\":[\"Зафиксируйте контракт спекой.\"],\"MRsrOn\":[\"Агенты получают контекст проекта через MCP. В средах, которые поддерживают хуки, контекст также поступает через них.\"],\"MZmD1l\":[\"Связь <0>implements</0> — отдельный MCP-вызов, посмотрите и подтвердите.\"],\"MqNG6n\":[\"Спасибо! Мы свяжемся с вами.\"],\"MtOieb\":[\"Подсветит 2-3 «горячих» модуля, которые стоит захватить следующими.\"],\"MtTLRh\":[\"пример\"],\"MynHgF\":[\"Подключите плагин, если агент его поддерживает\"],\"N2C89m\":[\"Справочник\"],\"N2UV5e\":[\"Для работы плагина Archcore CLI должен быть доступен через PATH.\"],\"N4omzb\":[\"Смысл держать решения, правила и гайды в репозитории в том, что они попадают в рабочий набор агента автоматически, до того как вы начнёте менять код, а не после.\"],\"N4qXFV\":[\"Добавьте плагин через панель Plugins, затем зарегистрируйте MCP для проекта.\"],\"NBdogM\":[\"PowerShell: одна строка с irm.\"],\"NG6la9\":[\"how-to\"],\"NG6rqk\":[\"Если вы пользуетесь Claude Code или Cursor — да: плагин использует CLI под капотом и добавляет intent-based слэш-команды. Ставьте CLI отдельно, если нужен базовый слой контекста или вы работаете с другим MCP-совместимым агентом.\"],\"NIRf3v\":[\"Пример документов проекта\"],\"NK7O34\":[\"Повседневный контекст не требует команд — хуки подставляют подходящие правила прямо во время правок. CLI нужен как обязательное условие: плагин вызывает <0>archcore</0> из вашего PATH.\"],\"NLzKIW\":[\"Как пользоваться Archcore: первый запуск и шесть задач\"],\"NVyKUB\":[\"MCP регистрируется автоматически. CLI поставится сам при первом вызове, если его ещё нет в PATH.\"],\"NXbnO1\":[\"Зачем здесь CLI: больше контроля — вы решаете, когда (и стоит ли) переходить к PRD. Удобно, если идея ещё может умереть в обсуждении.\"],\"NdQwaM\":[\"Скопируйте выделенный текст инструкций вручную.\"],\"Neb02T\":[\"Выберите точку входа и пройдите установку и проверку.\"],\"NfoDrN\":[\"Затем выполните archcore mcp install --agent cursor в папке проекта, чтобы подключить инструменты работы с документами.\"],\"NkUjTZ\":[\"Готовит спеку, описывающую контракт, а не реализацию.\"],\"Nq2YpA\":[\"Что мы могли бы построить\"],\"Nq7xmq\":[\"Изменение правила приходит диффом, который кто-то утверждает\"],\"NvwAWi\":[\"Все три документа окажутся в рабочем контексте агента до того, как вы попросите что-то изменить. Хук сессии делает это автоматически, когда вы открываете файл биллинга.\"],\"O/4Jtd\":[\"Откройте новую сессию в этом проекте и попросите агента:\"],\"O1XTW9\":[\"Один цикл Archcore на живой фиче, от init до review. Каждый шаг — фраза, которую вы говорите агенту, и файл, который после неё остаётся.\"],\"O3Mn6H\":[\"Команда archcore init создаёт .archcore/ для документов проекта и конфигурации.\"],\"O7bvB8\":[\"Переносится между инструментами\"],\"OHEzdv\":[\"Claude Code, Cursor, Codex и Copilot выдают код, который игнорирует ваши соглашения, ADR и ранее принятые решения.\"],\"OHHpZa\":[\"Проверьте код\"],\"OQQXXy\":[\"Когда использовать spec, doc или guide, смотрите справочник типов документов в документации.\"],\"OQtSWi\":[\"Slash-команды, скиллы и защитные проверки работают внутри Claude Code, Cursor, Codex CLI и GitHub Copilot. Остальные агенты получают тот же контекст через MCP. Если среда поддерживает хуки, контекст также поступает автоматически.\"],\"OSvXhR\":[\"Есть идея, контекста ещё нет\"],\"OWIRIH\":[\"Вытащить решение из окна чата\"],\"OZ98RW\":[\"Инструкции интеграции\"],\"OdCc84\":[\"Зачем здесь CLI: больше контроля. Вы сами выбираете типы связей (related против depends_on и так далее), а не соглашаетесь с тем, что предложит плагин.\"],\"OfPlYG\":[\"Настройка MCP через CLI.\"],\"OkKIqZ\":[\"Перестаньте заново объяснять свой репозиторий<0/>каждому AI-агенту.\"],\"OlFf9i\":[\"Запрос\"],\"Oos8fo\":[\"Скопировать команду\"],\"OtxqXt\":[\"Какая платформа?\"],\"P1g1vS\":[\"Должны появиться семь команд /archcore:*.\"],\"P21/tV\":[\"<0>init</0> сам найдёт установленные агенты (Claude Code, Cursor, Copilot, Gemini CLI…) и пропишет MCP + хуки для каждого. Идемпотентно — можно перезапускать.\"],\"P3Oyq2\":[\"Спроектируйте контекст, с которым работают ваши агенты\"],\"P3S9iP\":[\"Пусть AI-агент работает так,<0/>будто уже знает ваш репозиторий.\"],\"P5N5oF\":[\"Зачем здесь CLI: больше контроля. Каждое действие сводится к именованному вызову MCP: его можно повторить, версионировать или запустить в CI.\"],\"PAyQle\":[\"Ничего не появилось? Обычно дело в том, что CLI нет в PATH — проверьте <0>archcore --version</0>. В Copilot отсутствие инструментов означает, что пропущен шаг 2 (<1>archcore init --agent copilot</1>).\"],\"PDXxx4\":[\"Claude Code, Cursor, Codex CLI — один источник истины.\"],\"PNWz93\":[\"Хукам нужен экспериментальный флаг Codex; на Windows не работают\"],\"PT1/yk\":[\"Зачем здесь CLI: статус занимает одну команду в терминале, без похода к агенту. Удобно в pre-commit хуках и проверках на PR.\"],\"PWi5FH\":[\"Ваша первая полезная команда после установки — на свежем репозитории.\"],\"Pa98n5\":[\"<0>archcore init</0> подключает тех агентов, которыми вы уже пользуетесь. Каждый читает и пишет один и тот же каталог <1>.archcore/</1> в вашем репозитории.\"],\"PiJDpp\":[\"Выберите агентов для настройки. CLI запишет их конфигурацию MCP и установит хуки там, где они поддерживаются.\"],\"Plifa/\":[\"Посмотрите, как пользоваться Archcore: от init до review.\"],\"Plituu\":[\"Контекст между командами\"],\"Q0XbXr\":[\"типизированные контракты\"],\"Q4k5v4\":[\"Интерактивный тур\"],\"Q638Qv\":[\"Пока нечего фиксировать? Скажите «просто план». Шаги, которые уже закрыты существующим документом, закроются сами, а остальные пройдут без вопросов.\"],\"Q7cB7m\":[\"Вторая команда подключает MCP к этому проекту. После неё перезапустите Copilot. Интеграция предназначена для Copilot CLI.\"],\"Q8HGwu\":[\"Зачем здесь CLI: больше контроля. Вы выбираете тип документа, путь и момент записи. Работает с любым агентом с MCP (Gemini CLI, OpenCode, Roo Code, Cline).\"],\"QJVkKW\":[\"Выберите путь\"],\"QJactz\":[\"Copilot CLI\"],\"QLCpfo\":[\"Список пуст? Посмотрите раздел plugin troubleshooting в доках. Обычно дело в том, что CLI нет в PATH, либо в Codex выключен флаг <0>plugin_hooks</0>.\"],\"QN8G+b\":[\"Сверить изменения и документацию друг с другом\"],\"QPFsJw\":[\"Спеки описывают, что система обязана делать: интерфейсы, инварианты, крайние случаи. Они стоят между PRD (это «зачем») и планами (это «как»).\"],\"QQ4422\":[\"Archcore хранит спецификации, архитектуру, решения, правила и планы в Git и отдаёт AI-агентам разработки нужный контекст проекта прямо во время работы.\"],\"QSJjj6\":[\"Нужные правила и ADR приходят до вашей правки — а потом проверьте ветку.\"],\"QTbrC0\":[\"Опишите, как работает модуль уведомлений.\"],\"QXS2lS\":[\"Привычнее ставить прямо из агента? Посмотрите установку плагина по хостам\"],\"QftQCM\":[\"Запускает каскад трека <0>product</0> — первая остановка — <1>.idea.md</1>.\"],\"QoLx/E\":[\"Почувствуйте разницу\"],\"QqgVn8\":[\"Уже есть файлы инструкций?\"],\"Qr2FGk\":[\"MCP отдаёт 10 инструментов и 5 промпт-каскадов. Подходит для Copilot, Gemini CLI, OpenCode, Cline и пайплайнов.\"],\"QsCwpX\":[\"Зачем здесь CLI: больше контроля — каждый связанный документ проходит через явный MCP-вызов. Можно собрать скрипт и засевать любому своему агенту нужный контекст на старте сессии.\"],\"QshkEi\":[\"В Codex выполните <0>/plugins</0>, откройте Archcore и выберите Install plugin. MCP регистрируется автоматически. Хуки в Codex экспериментальные. Включите их через <1>codex --enable hooks</1> и учтите, что на Windows они не работают.\"],\"R/zLPd\":[\"Найти нужный скилл в каталоге\"],\"R1+hDd\":[\"Распознаёт это как решение и запускает трек решений, готовя <0>use-postgres.adr.md</0> со статусом, контекстом, решением и последствиями.\"],\"R7k68Z\":[\"Установить плагин\"],\"RCCEvQ\":[\"Файлы-инструкции — плоская память: один инструмент, один файл. Archcore структурирован: типизированные документы (ADR, правила, планы, гайды, спеки) со связями, версионируемой историей, которые читаются и пишутся во время реальной работы и переиспользуются всеми агентами.\"],\"RFZ4WX\":[\"Open source · Local-first · Без телеметрии\"],\"RPmPM9\":[\"Готовы попробовать? К установке\"],\"RR3I49\":[\"Каскад выдал вам четыре связанных документа. Как пустить их в работу в следующей сессии кодинга — ниже.\"],\"RUGmEt\":[\"Что вы получаете\"],\"RZELX4\":[\"Логичный код. Просто не так, как устроен этот репозиторий.\"],\"RaybMl\":[\"Дальше по кругу. Следующий план стартует уже со всем, что записали три предыдущих шага.\"],\"Rcherv\":[\"конфиг агентов\"],\"RhZb1C\":[\"Плагин добавляет навыки настройки, планирования, документирования и проверки в Claude Code, Cursor, Codex CLI и GitHub Copilot CLI. Он использует тот же CLI и те же документы проекта. Остальные MCP-агенты работают с CLI напрямую.\"],\"Ri0JTV\":[\"Затем <0>add_relation(rule implements spec)</0> и <1>add_relation(guide related rule)</1>.\"],\"Rsjgm0\":[\"Экспериментальная\"],\"RvqBD7\":[\"Часть поведения живёт сразу в нескольких папках: доставка вебхуков, auth-middleware, ретраи в очереди. Эти спеки самые ценные, потому что их агенту тяжелее всего нагрепать.\"],\"S+IECG\":[\"Тот же промпт. Другой агент.\"],\"S38CFD\":[\"Откройте Cursor → Plugins → вставьте этот URL:\"],\"SAYDjR\":[\"Сделать репозиторий читаемым\"],\"SDvMd5\":[\"Ничего не появилось? Обычно дело в том, что CLI нет в PATH. Проверьте <0>archcore --version</0>. В Copilot отсутствие инструментов для документов означает, что пропущен шаг 2 (<1>archcore init --agent copilot</1>).\"],\"SMnqPJ\":[\"На сегодня восемь — через MCP и хуки сессий: Claude Code, Cursor, Gemini CLI, GitHub Copilot, OpenCode, Codex CLI, Roo Code и Cline. Запустите archcore mcp install или archcore hooks install, чтобы подключить нужного.\"],\"SaF/hY\":[\"Файлы инструкций с привязкой к путям сохраняют свою область, но получают статус, отметки времени и связи, поэтому вы видите, что ещё в силе, а что отменило более позднее решение.\"],\"SbHCca\":[\"Поставить, прочитать репозиторий, что-нибудь записать.\"],\"SdgK1J\":[\"Поставьте\"],\"SnNB73\":[\"Контекстная инженерия для AI-агентов разработки\"],\"SnzUBh\":[\"За один проход получаете полную цепочку решений, правил и гайдов — связи прописываются автоматически.\"],\"SoekFr\":[\"Git-нативный контекст\"],\"SqgLxh\":[\"MCP · Локально · Работает на macOS, Linux, Windows\"],\"Srbs2i\":[\"Продолжайте в той же сессии:\"],\"Suz5DL\":[\"MCP регистрируется автоматически. А вот CLI должен быть в PATH: плагин его запускает, но никогда не ставит сам. Поставьте CLI и запустите <0>archcore init</0>, и оба шага закроются разом.\"],\"SvmN/l\":[\"Один бинарник, локальный MCP в репозитории. macOS, Linux, Windows.\"],\"SzLRcr\":[\"Готовит черновик <0>use-postgres.adr.md</0> со статусом, контекстом, решением и последствиями.\"],\"T+KHR2\":[\"Запустите в терминале:\"],\"T/qfGW\":[\"Запустите в терминале\"],\"T0HRX+\":[\"Спланируйте переделку авторизации.\"],\"T6EPDV\":[\"Нужно ли устанавливать CLI отдельно?\"],\"T7Pc8u\":[\"Установите Archcore и дайте агенту контекст проекта. Планируйте изменения, сохраняйте решения и проверяйте, что код им соответствует.\"],\"T8aUxQ\":[\"Новый файл окажется в <0>.archcore/</0> с уже заполненным frontmatter.\"],\"TJcNol\":[\"Логичный код — просто не так, как устроен этот репозиторий.\"],\"TKQ7K+\":[\"Установить\"],\"TLywSS\":[\"Spec-Driven Development\"],\"TZfRo7\":[\"Агент изучает репозиторий и предлагает документы об архитектуре, правилах и основных модулях. Вы проверяете предложение до того, как Archcore сохранит документы в .archcore/.\"],\"TZyoiv\":[\"Запустите в терминале:\"],\"TbjyhA\":[\"Документация\"],\"Tribf1\":[\"Читать документацию CLI\"],\"TskoZY\":[\"Ручная настройка MCP.\"],\"U5YgSM\":[\"Мой код куда-то отправляется?\"],\"U6kH6E\":[\"Между этими четырьмя шагами команд нет вовсе. Хуки подносят агенту спецификацию и ADR прямо во время правок, а каждая сессия начинается со сводки: что решено и что в работе.\"],\"UDzdXE\":[\"Контракт, который должен держать этот файл.\"],\"UKNsgh\":[\"Выполните в терминале, затем установите через /plugins:\"],\"UPj2am\":[\"Ещё до правки хук подставляет <0>billing-format.spec.md</0>.\"],\"URzSV7\":[\"Посмотреть, как пользуются Archcore\"],\"UUsJ/6\":[\"Универсальные подсказки для вашего кодбейза\"],\"UYnBYw\":[\"Установить\"],\"UaYHJk\":[\"Создаёт .archcore/ в репозитории\"],\"UpT5lx\":[\"Управляемое развёртывание, когда понадобится команде\"],\"Url9XE\":[\"Сначала зафиксируйте сырую идею.\"],\"UuZQZE\":[\"Поставить звезду Archcore на GitHub\"],\"V2PGGj\":[\"Зафиксировать то, на чём сошлись\"],\"V3aydv\":[\"Git-нативный контекст проекта<0/>для любого AI-агента разработки.\"],\"V3svl/\":[\"Обратитесь к агенту с запросом из примера или вызовите указанную slash-команду. Команды доступны в Claude Code, Cursor, Codex CLI и Copilot. Другие агенты работают с Archcore через MCP.\"],\"V74qGC\":[\"Всё остальное, что говорит на MCP, работает так же: CLI поднимается как локальный MCP-сервер, а не как отдельная интеграция под каждого вендора.\"],\"V75l6P\":[\"PowerShell — одна irm-строчка.\"],\"V7Sase\":[\"Плагин работает в четырёх агентах. Настройка MCP и поддержка хуков у них различаются.\"],\"V9A8RX\":[\"Скопировано ✓\"],\"VCyNJ8\":[\"Первый запуск и шесть задач\"],\"VJ1BJR\":[\"Посмотрите в действии, в интерактивном разборе.\"],\"VjfG6p\":[\"Во время работы над кодом хуки передают агенту нужные спецификации и решения, если он поддерживает хуки. В начале сессии они дают сводку решений и текущих задач. Другие агенты могут читать те же документы через MCP.\"],\"VkB1kO\":[\"Команда <0>\",[\"importCommand\"],\"</0> импортирует файлы инструкций, которые вы уже написали (CLAUDE.md, AGENTS.md, .cursorrules, .cursor/rules/*), как типизированные документы. Написанный вами контекст переносится, он просто перестаёт быть одним плоским файлом на инструмент.\"],\"VoCS/B\":[\"Прежде чем агент тронет код, он сам подгружает правила, решения и паттерны для этого пути — больше не нужно переклеивать соглашения в каждый новый чат.\"],\"VoO8gY\":[\"MCP и хуки. Проверьте параметр hooks в вашей версии Codex. В Windows хуки не работают.\"],\"Vw/VYd\":[\"Материалы по миграции\"],\"Vyv5eG\":[\"Он принадлежит репозиторию, а не одному ноутбуку.\"],\"W0nOpL\":[\"Плагин добавляет агенту навыки Archcore для планирования, документирования и проверки изменений. Он использует CLI и те же документы проекта.\"],\"W1kRzO\":[\"<0>create_document(type=plan)</0> с фазами, критериями приёмки и зависимостями.\"],\"W39KaQ\":[\"Открыть на GitHub →\"],\"W784wf\":[\"Дайте Claude Code, Cursor, Codex и Copilot<0/>понимание вашей кодовой базы.\"],\"W92HqV\":[\"GitHub Copilot CLI\"],\"WDx9Dc\":[\"Какие AI-агенты поддерживаются?\"],\"WGLudE\":[\"Проверяет ветку в обе стороны: код, который сломал документ, и документы, от которых код ушёл вперёд.\"],\"WHLVVp\":[\"Импортирует существующие <0>CLAUDE.md</0>, <1>AGENTS.md</1> или <2>.cursorrules</2>, чтобы не начинать с нуля.\"],\"WIBnUG\":[\"Archcore на GitHub\"],\"WJUZzd\":[\"Сегодня — бесплатно и локально.\"],\"WN/cAT\":[\"Гайд по миграции\"],\"WN0Q6e\":[\"Писать код, когда правила уже загружены\"],\"WOF7mM\":[\"В каждом агенте плагин ставится чуть по-разному. Покажем установку одной командой для вашего.\"],\"WOdWHS\":[\"При настройке выберите агентов, которыми вы пользуетесь. Archcore настроит их подключение к проекту.\"],\"WQLVJ0\":[\"Переиспользует существующий паттерн middleware\"],\"WRnqIw\":[\"Контекст — это не промпт и не окно побольше. Archcore делает знание о проекте явным, структурным, выборочным, версионируемым и доступным всем агентам разработки.\"],\"WbNcwF\":[\"Зачем здесь CLI: больше контроля — форму каскада и типы связей выбираете вручную, не принимая дефолты плагина. Скриптуется для пакетных операций в CI.\"],\"WeXKFI\":[\"Нет. archcore init импортирует ваши существующие файлы инструкций (CLAUDE.md, AGENTS.md, .cursorrules, .cursor/rules/*) как структурированные документы, поэтому написанный вами контекст переносится.\"],\"Wgfg4K\":[\"Самая дешёвая единица «видения» — <0>.idea.md</0>: один абзац намерения, без обязательств. Сделайте её до того, как браться за PRD или план.\"],\"WkUkGL\":[\"Полезные следующие шаги:\"],\"Wlp9hf\":[\"Выберите вариант, чтобы продолжить.\"],\"WlsM5c\":[\"Экспериментальная · Пока не проверена\"],\"Wp4MBP\":[\"Открыть тур\"],\"WpQnCf\":[\"Без установки. Посмотри, что именно запустишь.\"],\"WreFh5\":[\"Агент использует контекст проекта, чтобы описать ограничение запросов в спецификации и разбить реализацию на задачи. Затем вы можете писать код по этому плану.\"],\"X+BL/U\":[\"Что у вас сейчас\"],\"X30ptb\":[\"Работает поверх Archcore CLI · Skills · Subagents · Hooks\"],\"XHlqkT\":[\"Положите в репозиторий первую единицу структурированного контекста — правило для стека, гайд по запуску или первое решение, — чтобы агенту было что читать.\"],\"XNWf5L\":[\"Сам прописывает <0>add_relation(prd implements idea)</0>.\"],\"XSMKRv\":[\"Пока нечего фиксировать? Скажите «просто план» — шаги, которые уже закрыты существующим документом, закроются сами, а остальные пройдут без вопросов.\"],\"XSgmle\":[\"Обе точки входа читают и пишут одну и ту же папку <0>.archcore/</0>. Выбирайте по агенту, которым пользуетесь, а не по рекомендации.\"],\"Xbw/Em\":[\"Опишите проект\"],\"XhXmzW\":[\"На этой странице\"],\"Xq8mMn\":[\"Archcore на GitHub.\"],\"Xs9bmm\":[\"Три хоста сегодня. Любой MCP-агент — через CLI.\"],\"Y2J/eJ\":[\"Разверните Archcore Team\"],\"Y3nTBU\":[\"Пусть AI-агент работает так, будто уже знает ваш репозиторий.\"],\"Y6A5TY\":[\"Archcore CLI создаёт .archcore/, подключает MCP и хуки и позволяет агентам читать и записывать решения, правила, планы и гайды прямо из Git.\"],\"YCG3WH\":[\"MCP + хуки сессии\"],\"YCQ8fK\":[\"Откройте кодинг-агента в корне проекта и задайте вопрос, для которого нужен MCP. Если агент отвечает, значит, MCP подключён.\"],\"YCq0BM\":[\"Один запрос от начала до конца\"],\"YGZaoI\":[\"MCP даёт 10 инструментов для работы с документами. Подходит для Gemini CLI, OpenCode, Roo Code, Cline и пайплайнов.\"],\"YHbfre\":[\"В новом диалоге выполните:\"],\"YIYyYF\":[\"Решения, правила и паттерны как документы\"],\"YK9joI\":[\"Да — плагин всегда использует тот archcore, который найдёт в PATH. Ставьте его как удобно (curl, PowerShell, сборка из исходников) — см. https://docs.archcore.ai/cli/install/.\"],\"YNBnHA\":[\"Запускает трек <0>sdd</0> по умолчанию. Первая остановка: <1>.idea.md</1>.\"],\"YTGdTn\":[\"Плагин — это 7 slash-команд. Вот что каждая из них даёт вам.\"],\"YVW2yu\":[\"У меня уже есть CLAUDE.md или .cursor/rules. Начинать заново?\"],\"YW60pq\":[\"Два вызова <0>create_document</0> — одно правило, один гайд.\"],\"Ya2qA4\":[\"FAQ по CLI\"],\"Yai5t0\":[\"Спецификация лимитов и правило по API приезжают вместе с правкой, искать их не приходится.\"],\"YhG3In\":[\"Подтягивает правило по форматам ошибок в src/auth/\"],\"Yki+yH\":[\"Превратить идею в чёткий план реализации\"],\"Ykn3ee\":[\"Проверка охватывает только записанные прогоны\"],\"YxGMld\":[\"Archcore Plugin — память репозитория для AI-агентов\"],\"Z1qTW3\":[\"Зачем здесь CLI: больше контроля. Вы вручную задаёте форму каскада и типы связей, а не соглашаетесь с тем, что предложит плагин. Скриптуется в CI для пакетных операций.\"],\"Z3XiYB\":[\"Одна возможность: спецификация и план.\"],\"ZLTQlB\":[\"Навигация по сайту\"],\"ZNWRnh\":[\"Archcore CLI — память репозитория для любого AI-агента разработки\"],\"ZS6lkM\":[\"Да — одна глобальная установка. Запустите curl -fsSL https://archcore.ai/install.sh | bash (или эквивалент на PowerShell в Windows), затем добавьте плагин. MCP запускает archcore из вашего PATH.\"],\"ZjWAOw\":[\"<0>refund-policy.rule.md</0> — правило, которому ваши правки должны соответствовать.\"],\"Zk/jW3\":[\"Claude Code, Cursor, Codex CLI, GitHub Copilot CLI, Gemini CLI, OpenCode, Roo Code и Cline. В Cline MCP настраивается вручную. Поддержка хуков различается; подробности есть в списке агентов выше.\"],\"ZlSIyH\":[\"archcore init создаёт .archcore/ в проекте\"],\"ZoZV/a\":[\"Claude Code (production), Cursor 2.5+ (реализовано) и Codex CLI 0.117+ (реализовано). GitHub Copilot — в планах. Для других агентов с MCP используйте CLI напрямую.\"],\"a+Ulsb\":[\"Здесь команды нет вообще. Она работает на том, что вы уже записали, и потому весь остальной список имеет смысл.\"],\"a0lim6\":[\"Зачем здесь CLI: больше контроля. Вставьте это в CI-шаг перед мержем, и расхождения перестанут проскакивать мимо ревью.\"],\"a30BFY\":[\"Плагин работает внутри Claude Code, Cursor 2.5+ и Codex CLI 0.117+. CLI работает с любым MCP-агентом — GitHub Copilot, Gemini CLI, OpenCode, Roo Code, Cline — и скриптуется в CI.\"],\"a6V80+\":[\"Установка, быстрый старт, захват кода или работа с контекстом. Выберите путь.\"],\"a6VFGb\":[\"Источник правды принадлежит команде\"],\"a7KWcg\":[\"За пять минут у вас уже есть решение, правило и гайд. Выберите одну из опций ниже, чтобы продолжить цикл.\"],\"a7cM/B\":[\"Правки с учётом контекста\"],\"a81bnj\":[\"Локальный MCP, готов для агентов, версионируется вместе с кодом.\"],\"aGERSi\":[\"Вы должны увидеть четыре команды: init, plan, document, review.\"],\"aNqJC7\":[\"Соедините два инструмента\"],\"aPTjRl\":[\"Поднимать ничего не надо. Контекст лежит в репозитории, ездит вместе с ним через Git и достаётся любому агенту, которого вы откроете.\"],\"aVlfDQ\":[\"Не знаете, с чего начать?\"],\"aX5YcY\":[\"Token bucket в Redis\"],\"aX7X5e\":[\"Первая настройка\"],\"aYKuBp\":[\"Один цикл на живой фиче: init, plan, document, review.\"],\"aa3q44\":[\"Опишите задачу обычными словами, и Archcore сам её направит. Команды <0>/archcore:*</0> ниже просто дают быстрый доступ к тем же сценариям.\"],\"adI8Hm\":[\"Выполните archcore init в репозитории, затем выберите агентов, которыми пользуетесь.\"],\"age+/6\":[\"Вы копируете одни и те же правила архитектуры в каждый новый чат. Агент забывает их сразу, как только разговор заканчивается.\"],\"as/7uX\":[\"Записать то, что живёт только в коде\"],\"astDB+\":[\"Блог\"],\"aw56KM\":[\"Зачем здесь CLI: больше контроля — вы выбираете тип документа, путь и момент записи. Работает с любым агентом с MCP (Gemini CLI, OpenCode, Roo Code, Cline).\"],\"aweRxW\":[\"Поставить звезду плагину на GitHub\"],\"b+5vn5\":[\"Настраиваете конкретного агента?\"],\"b77eEX\":[\"Только что созданный план — теперь источник истины для агента в этой работе.\"],\"bF8787\":[\"пройдено\"],\"bJKUM8\":[\"Один бинарник. Локальный MCP в репозитории. macOS, Linux, Windows, без внешних сервисов.\"],\"bLzRkX\":[\"Плагин регистрирует MCP автоматически.\"],\"bNgxxz\":[\"Проектирование того, что агенту сообщают до действия и что проверяет его после, называется harness engineering. <0>Разбор harness engineering</0>.\"],\"baYt8N\":[\"Скажите, что вам нужно. Archcore это запишет.\"],\"bcxKHI\":[\"Slash-команды, скиллы и защитные проверки работают внутри Claude Code, Cursor, Codex CLI и GitHub Copilot. Остальные агенты получают тот же контекст через MCP. Если среда поддерживает хуки, документы с требованиями к файлу приходят до того, как агент его изменит, без единой команды. Это и есть <0>контекстная инженерия для AI-агентов разработки</0>.\"],\"be8kJ8\":[\"Каждая сессия начинается со сводки: что решено и что в работе.\"],\"bg9kJw\":[\"Обычные фразы или slash-команда. Каждый шаг использует то, что сохранил предыдущий, поэтому проверка в конце знает, что было в плане и в решении.\"],\"bhQjya\":[\"Быстрый старт в вашем проекте\"],\"bhbyT1\":[\"Даёт агентам просматривать, искать и обновлять документы Archcore.\"],\"bk6b6x\":[\"Пока используйте путь через CLI\"],\"blFINL\":[\"Зачем здесь CLI: больше контроля. Предсказуемый тип означает, что документ ляжет ровно туда, куда вы хотите, в структуре категорий (knowledge / vision / experience).\"],\"bo7TXa\":[\"Переключите трек каскада:\"],\"boXjpz\":[\"Плагин Archcore загружает вашу архитектуру, правила и решения в Claude Code, Cursor и Codex CLI, чтобы агент следовал договорённостям вашей команды.\"],\"bwG3Mj\":[\"Посмотреть путь через CLI\"],\"bx1EG6\":[\"Агент читает через <0>get_document</0>, пишет через <1>create_document(type=prd)</1>.\"],\"c/6GYl\":[\"FAQ по плагину\"],\"c1QSvG\":[\"Спеки описывают, что делает система. Правила — что должны делать люди (и агенты), когда её меняют. Гайды проводят новых через это.\"],\"c4vO9F\":[\"Начинать заново не нужно.\"],\"c6uBjZ\":[\"В Copilot плагин не поставляет MCP-сервер, поэтому шаг 2 настраивает его для репозитория — без него у агента не будет инструментов для документов. Только Copilot CLI; в режиме агента VS Code самостоятельная установка плагина недоступна.\"],\"c7M77D\":[\"Добавьте spec-driven разработку и автоматический контекст проекта в Claude Code, Cursor, Codex CLI и GitHub Copilot CLI с помощью Archcore.\"],\"c9zIBm\":[\"Подключение — две команды: <0>archcore mcp install</0> регистрирует локальный MCP-сервер, <1>archcore hooks install</1> добавляет хуки сессии там, где хост их поддерживает.\"],\"cB/JMP\":[\"Перезапустите агента, чтобы сработал session-start хук, и убедитесь, что slash-команды подцепились.\"],\"cCqsZC\":[\"Формат ошибок в src/api/\"],\"cGO0oE\":[\"Агент не понял вопрос? Запустите <0>archcore doctor</0> — он за один проход проверит регистрацию MCP, установку хуков и гигиену тегов.\"],\"cIynCc\":[\"Зафиксируйте решение или опишите существующий код.\"],\"cKleNL\":[\"Агент разбирается, как устроен проект, и предлагает первый набор документов: стек, запуск, обзор архитектуры и спецификации на модули, которые меняются чаще прочих. Всё это он показывает одним предпросмотром и ничего не пишет, пока вы не подтвердите.\"],\"cLalVW\":[\"Другой MCP-агент? Перейдите к CLI\"],\"cO3Zgo\":[\"← Все интеграции\"],\"cP7QqC\":[\"Агент сверяет изменения в коде со спецификацией из шага 2 и решением из шага 3. Он отмечает нарушения требований в коде и документы, которые ему больше не соответствуют.\"],\"cPbE+b\":[\"Аудит после правок.\"],\"cbjZxy\":[\"В GitHub Copilot CLI плагин не может нести собственный MCP-сервер, поэтому однократная настройка проекта через <0>archcore init --agent copilot</0> обязательна, а не опциональна — без неё инструментов для документов не будет.\"],\"cd+MZ3\":[\"Определите, что строите, и держите определение там, где идёт работа. Спецификация, которая задала объём фичи, — та самая, с которой ревью сверяет вашу ветку и с которой начинается следующий план.\"],\"cfjqf1\":[\"Четыре команды выше — это то, что вы набираете. Остальное происходит само: когда агент открывает файл, Archcore отдаёт ему документы, которые этот файл ограничивают, ещё до правки.\"],\"chL5IG\":[\"Сообщество\"],\"ci+lOf\":[\"Обновление и отключение\"],\"cj/u4x\":[\"Документация по установке\"],\"cth0F2\":[\"Хуки сессии передают сводку решений проекта и текущих задач. У агентов с хуками перед записью нужные правила и спецификации поступают до правки. Остальные агенты читают контекст проекта через MCP.\"],\"ctijSM\":[\"Если вы уже ведёте CLAUDE.md, идея вам знакома. Archcore добавляет типизированные документы, связи и историю, а <0>archcore init</0> импортирует уже написанные вами файлы инструкций. <1>Почему контексту проекта место в Git</1>.\"],\"cyjAPW\":[\"Выберите путь — установка, быстрый старт, захват существующего кода или использование решения — и пройдите по командам, которые можно скопировать. У веток с plugin и CLI есть переключатель.\"],\"czCcnU\":[\"В .archcore/ внутри вашего репозитория. Markdown с YAML-фронтматтером, версионируется вместе с кодом. Без внешних сервисов, аккаунтов и баз данных.\"],\"d4nRaY\":[\"Три команды установки дают Claude Code, Cursor и Codex CLI память, которая живёт рядом с кодом — и slash-команды, чтобы фиксировать новые решения по ходу работы.\"],\"dBzFDT\":[\"Запустите в шелле, затем спросите:\"],\"dDDf4e\":[\"Что спросить дальше:\"],\"dDW5Cs\":[\".cursorrules и разрозненные промпты\"],\"dF6vP6\":[\"Live\"],\"dI1NC4\":[\"Подгружает нужный контекст при старте сессии.\"],\"dMxJpL\":[\"Явный запрос типа отключает эвристику агента — на выходе получаете предсказуемый тип.\"],\"dNWCp+\":[\"Подтвердите, что можете использовать \",[\"names\"],\" и прочитали инструкции по совместной работе в этом проекте.\"],\"dSSbLL\":[\"Правила и решения\"],\"dVKU95\":[\"Для выбранных агентов с поддержкой плагина init также установит плагин. В Cursor его нужно добавить через панель Plugins.\"],\"dWYFl4\":[\"Решения, правила и гайды живут в репозитории ровно ради того, чтобы попадать в рабочий контекст агента автоматически — до правок, а не после.\"],\"dXz/cv\":[\"Плагин Archcore в маркетплейсе плагинов Cursor с MCP и slash-командами\"],\"da1Frg\":[\"Каждая команда пишет в <0>.archcore/</0>. Смотрите в PR, принимайте то, что подходит, остальное правьте.\"],\"da6N0D\":[\"Никаких внешних сервисов, аккаунтов и телеметрии.\"],\"djJRIW\":[\"Поддерживаемые агенты\"],\"dmENSE\":[\"Опишите структурными спецификациями и планами, что нужно построить, и держите их рядом с решениями, правилами и архитектурой, которые понадобятся агенту при реализации.\"],\"doHvL0\":[\"Один плоский файл под один инструмент превращается в типизированные документы, которые читает любой агент: соглашения становятся правилами, а рассуждения за ними превращаются в ADR.\"],\"dwpEY9\":[\"Настройка MCP-сервера, правка конфигов и поддержание их в актуальном виде — точно не то, что хочется делать сегодня.\"],\"dxTOmW\":[\"Копируете правила каждую сессию\"],\"dyKONw\":[\"Добавьте <0>--drift</0> для поиска устаревшего или <1>--deep</1> для полного аудита с проверкой покрытия и связей.\"],\"e14eeO\":[\"Archcore хранит ваши решения, правила и архитектуру как структурированные документы прямо в репозитории — и подгружает их агенту по MCP до того, как он начнёт править код.\"],\"e23jKm\":[\"Сохраните решения проекта для следующей задачи.\"],\"e5RszW\":[\"В Copilot плагин не поставляет MCP-сервер, поэтому шаг 2 регистрирует его на уровне проекта. Пропустите его, и инструментов для документов не будет вовсе. Выполните один раз на репозиторий и закоммитьте результат. Только Copilot CLI: в режиме агента VS Code самостоятельная установка плагина недоступна.\"],\"e6i9Fr\":[\"Показать инструкции целиком ↓\"],\"e7KNOU\":[\"Последний гейт каскада:\"],\"eDyLTc\":[\"Спецификация — часть контекста, а не весь контекст. Она живёт рядом с архитектурой, прежними решениями, ограничениями и правилами команды, которые агенту тоже нужны. <0>Spec-driven разработка для AI-агентов</0>.\"],\"eXKUMr\":[\"Находит установленных агентов\"],\"eYiTGs\":[\"Захватите сквозной пайплайн.\"],\"ebKuot\":[\"Если вы работаете в Claude Code, Cursor, Codex CLI или GitHub Copilot CLI, плагин добавляет slash-команды по намерению поверх того же CLI. Ставьте CLI отдельно, если нужен голый слой контекста или другой агент с поддержкой MCP.\"],\"ecTygm\":[\"Зафиксировать\"],\"ei0R30\":[\"Спланируйте лимиты запросов для публичного API.\"],\"ejDydy\":[\"Archcore хранит документы проекта локально в .archcore/. Ваш агент разработки может передавать фрагменты документов провайдеру модели. Аналитика установки и обновлений содержит сведения о версии и платформе; содержимое проекта в неё не входит. Подробности и способы отключения описаны в политике конфиденциальности.\"],\"endD30\":[\"Сверьте ветку с записанными решениями и правилами. Отметьте и устаревшие документы.\"],\"eySX86\":[\"Claude Code, Cursor, Codex, Copilot. Один источник правды.\"],\"f+2/Pr\":[\"Версионируется вместе с кодом\"],\"f1E7ZC\":[\"Запускает трек <0>sdd</0> по умолчанию — первая остановка <1>.idea.md</1>.\"],\"f20zqr\":[\"Записать ADR и (при желании) превратить его в командное правило, которое автоматически применится ко всем будущим правкам в этой области.\"],\"f6Dbqy\":[\"Базовый слой контекста. Один бинарник плюс MCP — работает с любым агентом, поддерживающим MCP, и подходит для CI.\"],\"fBuHIo\":[\"Какой контракт держать\"],\"fFLGyO\":[\"Настройка по каждому агенту\"],\"fN3AeL\":[\"Агент перестаёт угадывать вашу архитектуру по именам файлов и просто читает её.\"],\"fOStzb\":[\"Чтобы обновить, сначала посмотрите, что изменилось в инструкциях, и только потом заменяйте свою копию. Чтобы отключить, удалите добавленные инструкции из файла проекта. Оба инструмента и их документы остаются на месте.\"],\"fOuPPd\":[\"Плагин\"],\"fRhxba\":[\"Плагин подгружает нужный контекст перед правками и фиксирует каждое новое решение обратно в Git.\"],\"fSYs0W\":[\"ADR, где записан и вердикт, и рассуждение к нему, плюс предложение сразу написать командное правило, которое из него следует.\"],\"fUCfps\":[\"Archcore Plugin — Spec-Driven Development для AI-агентов разработки\"],\"fUKr39\":[\"Плагин Archcore добавляет spec-driven сценарии и автоматический контекст проекта в Claude Code, Cursor, Codex CLI и GitHub Copilot CLI. Спецификации, архитектура, решения, правила и планы живут в Git и применяются, пока агент работает.\"],\"fWsBTs\":[\"Что-то пошло не так. Попробуйте ещё раз.\"],\"fbvyGE\":[\"Зачем здесь CLI: больше контроля. Вы сами определяете область спеки и исключения, а не берёте то, что сгенерировал бы плагин.\"],\"fpk/AV\":[\"Агент читает ваш код. Причины, по которым он такой, агент прочитать не может. Archcore хранит эти причины рядом с кодом и отдаёт агенту нужную часть прямо во время работы.\"],\"fwrPh4\":[\"Введите корректный email.\"],\"g+7fCH\":[\"Готовит правило, которое фиксирует инварианты спеки, и гайд по типовым изменениям.\"],\"g7Tj0J\":[\"Вам не нужно помнить команду «загрузить контекст» — хуки делают это при каждой правке и в каждом новом диалоге.\"],\"g7gJBC\":[\"Начните с одной папки, которую агент постоянно переоткрывает заново. На выходе обычно <0>.spec.md</0> — контракт того, что модуль гарантирует.\"],\"gAhgji\":[\"Зачем нужен CLI\"],\"gJY76f\":[\"Выберите путь: установка, быстрый старт, описание существующего кода или работа с решением. Дальше пройдите по командам, которые можно копировать. Ветки, где есть и плагин, и CLI, дают переключатель.\"],\"gKHYg1\":[\"Каждый путь — короткий разбор с командами, которые можно копировать. У путей, где есть и плагин, и CLI, сверху переключатель, и его можно менять на любом шаге.\"],\"gNBVny\":[\"Повседневный контекст не требует команд. Хуки подставляют подходящие правила прямо во время правок. CLI нужен как обязательное условие: плагин вызывает <0>archcore</0> из вашего PATH.\"],\"gP4tG9\":[\"Одна установка даёт Claude Code, Cursor, Codex и Copilot память, которая живёт рядом с кодом: она подставляется автоматически во время правок, а slash-команды фиксируют новые решения по ходу работы.\"],\"gVPVeT\":[\"Смотреть плагин\"],\"gaxbak\":[\"Spec-driven разработка для AI-агентов\"],\"gc9hKT\":[\"Команды нет. Archcore делает это, пока вы работаете.\"],\"gcrbQE\":[\"Спецификация в <0>.archcore/notifications/delivery.spec.md</0>, написанная по коду, а не по памяти.\"],\"gfDYD0\":[\"Step four ends in a verdict per finding, not a summary: <0>spec-wrong</0> when the document is stale, <1>code-wrong</1> when the branch broke a decision, and <2>ok</2> when the two agree.\"],\"gsjmvJ\":[\"Нужные правила и ADR приходят до вашей правки, а потом вы проверяете ветку.\"],\"gxs/QL\":[\"Готовит черновик <0>auth-redesign.prd.md</0> с целями, не-целями, стейкхолдерами и метриками успеха.\"],\"gxuwrj\":[\"Да. Плагин вызывает archcore из PATH и не скачивает CLI. Установите CLI один раз, затем выполните шаги для своего агента, указанные выше.\"],\"h8NYws\":[\"Слэш-команды, навыки и ограничители прямо внутри хоста.\"],\"h9TUNk\":[\"Агент обходит <0>list_documents</0> + <1>list_relations</1> и возвращает отчёт.\"],\"hCCw4v\":[\"Записывает решение обратно как versioned-документ\"],\"hCsypc\":[\"Правки с контекстом — без команд\"],\"hDR3aB\":[\"Context Engineering\"],\"hEgSWe\":[\"Один плоский файл под один инструмент превращается в типизированные документы, которые прочитает любой агент: соглашения — в правила, причины за ними — в ADR.\"],\"hFthoo\":[\"Примеры\"],\"hIkTTD\":[\"Проходит ревью в пул-реквестах\"],\"hLiGLb\":[\"Финальная связь: <0>add_relation(plan implements spec)</0>.\"],\"hMJ8Zn\":[\"Покажет недостающие связи, осиротевшие документы и решения, чьи целевые пути в коде уехали.\"],\"hVilLZ\":[\"Что создаёт archcore init?\"],\"hX0Rmb\":[\"Никаких новых сервисов. Контекст живёт в репозитории и путешествует вместе с ним.\"],\"hXJCdB\":[\"Плагин Archcore для AI-агентов\"],\"hXzOVo\":[\"Далее\"],\"hYOnMZ\":[\"Подробнее\"],\"he3ygx\":[\"Копировать\"],\"heUUfo\":[\"Самая дешёвая единица vision-контекста называется <0>.idea.md</0>: один абзац намерения, пока без обязательств. Заведите его прежде, чем браться за PRD или план.\"],\"heb/Zg\":[\"Git-нативный контекст для AI-агентов разработки.\"],\"hwKPWZ\":[\"Плагин в действии\"],\"i0oy+F\":[\"Обратитесь к агенту обычными словами или используйте четыре команды по порядку: init, plan, document, review.\"],\"i3rNN3\":[\"Спецификация — часть контекста, а не весь контекст. Она живёт рядом с архитектурой, прежними решениями, ограничениями и правилами команды, которые агенту тоже нужны.\"],\"i4vNYk\":[\"Установка под конкретную среду\"],\"i78PMI\":[\"В Copilot плагин не поставляет MCP-сервер, поэтому шаг 2 настраивает его для репозитория. Пропустите его, и у агента не будет инструментов для документов. Только Copilot CLI; в режиме агента VS Code самостоятельная установка плагина недоступна.\"],\"i7cAu7\":[\"В новой сессии ничего не надо объяснять заново\"],\"iBvBfx\":[\"Используешь Cursor или Codex CLI? Все способы установки\"],\"iELNnf\":[\"Попробуйте прямо здесь\"],\"iEQQyu\":[\"Агент\"],\"iH8pgl\":[\"Назад\"],\"iNJzmR\":[\"Три вызова <0>create_document</0> через MCP: один ADR, одно правило, один гайд.\"],\"iRO/9t\":[\"Сначала вы правите черновик, и неверное прочтение не попадает в документ.\"],\"iSLIjg\":[\"Связать\"],\"iW0UfU\":[\"Какие команды попробовать дальше:\"],\"ifmaau\":[\"Агент идёт по ADR, который команда уже написала, вместо того чтобы сочинять свой.\"],\"ik8yJQ\":[\"Выборочный\"],\"ikqzYM\":[\"Хук сессии сам подгрузит нужный контекст в следующем разговоре — /context каждый раз вызывать не надо.\"],\"io2iMk\":[\"/archcore:init, /archcore:plan, /archcore:document и /archcore:review. Они отвечают за настройку, планирование, запись решений и проверку изменений. Можно обратиться к агенту и обычными словами.\"],\"iqyK78\":[\"1. Установите \",[\"names\"]],\"ivjd6f\":[\"С версии v0.7.0 для этого не нужна никакая команда: хук перед записью определяет правимый файл и подставляет то, что к нему относится, а сессия начинается со сводки решённого и текущего.\"],\"j2WEFa\":[\"У вас есть полная цепочка — идея, PRD, спека, план — связанная между собой. Следующая сессия, открывшая любой из них, сама подтянет остальные.\"],\"jB+rgl\":[\"Зачем здесь CLI: больше контроля — предсказуемый тип значит, что документ ляжет именно туда, куда нужно, в структуре категорий (knowledge / vision / experience).\"],\"jDC+I8\":[\"Spec-Driven Development и контекстная инженерия<0/>для AI-агентов разработки\"],\"jFHOpw\":[\"Все 4 команды сразу\"],\"jFWbEK\":[\"Агент вызывает <0>create_document(type=spec)</0> с деталями контракта прямо внутри.\"],\"jHiFGq\":[\"Как установить Archcore\"],\"jN/TwM\":[\"Вы принимаете реальное решение внутри агента — а через неделю никто, включая самого агента, не помнит почему.\"],\"jP1GRS\":[\"Два шага, оба обязательны.\"],\"jYsicM\":[\"Как использовать Archcore — интерактивный тур\"],\"jfrpM/\":[\"Зафиксируйте решение: берём token bucket в Redis.\"],\"jmyt1U\":[\"Запустите Archcore локально одной командой Docker. Регистрация и настройка не требуются.\"],\"jq+1V0\":[\"Четыре хоста сегодня. Любой MCP-агент — через CLI.\"],\"jwC8Il\":[\"Дайте прочитать репозиторий\"],\"k1oTSY\":[\"MCP (ручная настройка)\"],\"kMc7UE\":[\"Оба пути работают с одной и той же папкой <0>.archcore/</0>. Разница — в слое опыта.\"],\"kMkm1J\":[\"Скилл задаёт порядок действий агента для конкретной задачи. Эти четыре связывают описание проекта, планирование, запись решений и проверку кода. Каждый шаг использует контекст, сохранённый на предыдущих.\"],\"kOg3Ll\":[\"Plugin — слэш-команды · CLI — один бинарь.\"],\"kSdsW2\":[\"Агент подгружает то, что относится к файлу перед ним.\"],\"kWJmRL\":[\"Вы\"],\"kWxtNd\":[\"Связи проставляются автоматически: правило <0>implements</0> спеку, а гайд <1>related</1> к правилу.\"],\"kX0GJp\":[\"Спецификация и план, размером под то, что правка реально задевает. На правку вёрстки не появилось бы ни одного документа.\"],\"kf7aVx\":[\"The loop above has four commands. The work between them has none. When the agent opens a file, Archcore gives it the documents that constrain that file, before the edit.\"],\"kpwL6+\":[\"Агент использует MCP <0>create_document(type=spec)</0>.\"],\"ksUJrA\":[\"Как выглядит работа с Archcore: поставить один раз, дать агенту прочитать репозиторий, а дальше обычными фразами фиксировать решения, описывать код, планировать фичи и проверять ветки.\"],\"kxnNBZ\":[\"Поведение, размазанное по папкам, тоже годится. «Опишите, как устроена доставка вебхуков» соберёт все его части.\"],\"l1QGYU\":[\"Восемь через MCP: Claude Code, Cursor, Gemini CLI, GitHub Copilot, OpenCode, Codex CLI, Roo Code и Cline (ручная настройка). Пятеро из них получают ещё и хуки сессии — Claude Code, Cursor, Gemini CLI, Codex CLI и GitHub Copilot. Выполните archcore mcp install или archcore hooks install, чтобы подключить каждого.\"],\"l4ag9R\":[\"Дайте Claude Code, Cursor и Codex CLI<0/>понимание вашей кодовой базы.\"],\"l6wu4P\":[\"Рейт-лимит для публичного API\"],\"l8ZqFG\":[\"Справочные материалы и инструкции просятся так же, а выходят как doc или guide.\"],\"l8xUDX\":[\"Archcore хранит документы проекта локально и запускает MCP-сервер на вашем компьютере. Облачный сервер Archcore не нужен. При этом продолжают действовать настройки провайдера и обработки данных вашего агента.\"],\"lFO6HG\":[\"Контекст и реализация едут в одной ветке.\"],\"lFmMXE\":[\"не выполнено\"],\"lW59Bc\":[\"Создайте каталог для контекста\"],\"ldm2U/\":[\"Откройте Plugins → Add и вставьте URL:\"],\"lefqbw\":[\"Работает с Claude Code · Cursor · Codex CLI · Copilot · Gemini CLI · любым MCP-агентом. Открытый код, всё хранится локально.\"],\"lmMVX7\":[\"Решения становятся файлами\"],\"loc1jo\":[\"Нравится, куда это движется? Поставьте звезду на GitHub.\"],\"lptGWw\":[\"Нет. Отдельный бинарник. Всё в .archcore/ остаётся в вашем репозитории: ни серверов, ни баз, ни аккаунтов, ни внешних зависимостей.\"],\"lrKxw7\":[\"Сверьте ветку с записанными правилами и решениями в обе стороны — код, сломавший документ, и документы, от которых код ушёл вперёд.\"],\"lxRTiF\":[\"Работаете в Gemini CLI, OpenCode, Roo Code или Cline? CLI подключает все восемь поддерживаемых агентов через MCP. У пяти также есть хуки сессии; различия указаны на странице CLI.\"],\"lygedW\":[\"Нет. Автономный бинарник. Всё в .archcore/ остаётся в вашем репозитории — без серверов, баз данных, аккаунтов и внешних зависимостей.\"],\"m+Juw6\":[\"Или вызовите MCP-промпт <0>product_track</0> напрямую — он отработает весь каскад.\"],\"m0B+rF\":[\"Каждая команда пишет в <0>.archcore/</0> — посмотрите в PR, примите подходящее, остальное отредактируйте.\"],\"m1YSqO\":[\"MCP и хуки сессии. Передача контекста перед правкой недоступна.\"],\"mBn8AP\":[\"Что вы получаете в терминале:\"],\"mD9IaQ\":[\"Нужен другой формат? Попросите <0>type=doc</0> (справка) или <1>type=guide</1> (how-to).\"],\"mI5g+m\":[\"Зачем здесь CLI: больше контроля. Связи явные, их видно на ревью и можно переиграть. Удобно для задач, чувствительных к комплаенсу, вроде этого примера с auth.\"],\"mKpvDu\":[\"Смотреть CLI\"],\"mLyxZr\":[\"Добавь rate limiting на auth-эндпоинты.\"],\"mOm/wr\":[\"Первые пятнадцать минут, а дальше шесть задач, ради которых его запускают.\"],\"mSKOMz\":[\"Сохраняет выбор и его обоснование как запись архитектурного решения (ADR).\"],\"mXVOSZ\":[\"Проверка установки\"],\"mYGY3B\":[\"Дата\"],\"mYanpZ\":[\"Перейдите от идеи к PRD.\"],\"mcqg5X\":[\"Закрыть установку\"],\"mo7WnT\":[\"Архитектуру и договорённости приходится объяснять заново каждую сессию.\"],\"msgpY5\":[\"<0>CLAUDE.md</0>, <1>AGENTS.md</1> и <2>.cursor/rules/</2>, которые вы уже написали, переезжают сюда типизированными документами.\"],\"mvXoq5\":[\"MCP — ручная настройка\"],\"mzDVoG\":[\"Нет. В начале сессии агент получает компактный индекс ваших документов; полные документы подтягиваются по запросу через MCP — поиск, связи, точечное чтение — а не загружаются целиком.\"],\"n5fb8M\":[\"Закрыть подробности\"],\"nA8kxD\":[\"MCP\"],\"nBzdEO\":[\"Архитектура, спецификации, требования, решения, правила, планы и руководства лежат в <0>.archcore/</0> обычным Markdown и версионируются вместе с кодом, который описывают. Archcore поддерживает 19 типов документов, и изменение любого приходит диффом, который кто-то утверждает.\"],\"nX7m4W\":[\"Плагин Archcore загружает вашу архитектуру, правила и решения в Claude Code, Cursor, Codex CLI и GitHub Copilot CLI, чтобы агент перестал угадывать и начал следовать правде вашей команды.\"],\"nXpqGD\":[\"Зачем здесь CLI: больше контроля. Каждое действие сводится к именованному вызову MCP: его можно переиспользовать, версионировать или запустить в CI.\"],\"nbfdhU\":[\"Интеграции\"],\"nd3zgJ\":[\"Что с ним делают\"],\"niZVJZ\":[\"Инструмент командной строки Archcore. Настраивает контекст проекта и подключает ваших AI-агентов через MCP и поддерживаемые хуки.\"],\"nuR0yy\":[\"Контекстная инженерия для кода, который вы меняете\"],\"o1v4vM\":[\"3. Проверьте в новой сессии\"],\"o3KKP3\":[\"Чтобы агенты следовали твоей архитектуре, а не гадали по плоскому CLAUDE.md.\"],\"o3uJZY\":[\"Плоская память работает для одного разработчика. Не для команды, не для нескольких агентов, не через полгода.\"],\"o5UZfz\":[\"Проверяет ветку в обе стороны — код, сломавший документ, и документы, от которых код ушёл вперёд.\"],\"o6LKV9\":[\"Терминальный кодинг-агент от Anthropic.\"],\"oDnjKr\":[\"Правило про стек, гайд по запуску, обзор архитектуры и спецификация на каждый модуль, который меняется чаще прочих.\"],\"oG0Ori\":[\"Сформируйте план.\"],\"oJEeDf\":[\"Вы принимаете реальное решение внутри агента, а через неделю никто, включая самого агента, не помнит почему.\"],\"oRz3AS\":[\"Сценарий\"],\"oT/y8b\":[\"Эта версия пока не опубликована.\"],\"oel88E\":[\"Ловите расхождения до мержа\"],\"ofMBCe\":[\"Посмотрите, как это работает — интерактивный тур.\"],\"oitXe7\":[\"Опишите обычными словами, что нужно, и Archcore сам определит маршрут. Команды <0>/archcore:*</0> ниже — просто ярлыки к тем же трекам.\"],\"ok+MiR\":[\"Агент сохраняет выбор и его обоснование в записи архитектурного решения (ADR). В следующих задачах можно будет найти, почему для ограничения запросов вы выбрали Redis.\"],\"opAyUG\":[\"Знание о проекте становится файлами\"],\"oqHBQb\":[\"Ничего не хранится там, где вы не можете это прочитать и поправить.\"],\"ov0NaA\":[\"Открыть интерактивный тур\"],\"p0i0cE\":[\"Что добавляет плагин\"],\"p1OBUy\":[\"Установить CLI\"],\"p1hi8H\":[\"Один предпросмотр со всеми документами: вы читаете его до того, как Archcore что-то запишет.\"],\"p4RRoD\":[\"Запросите следующий документ, когда будете готовы, — вы ведёте каскад шаг за шагом.\"],\"p7YY0i\":[\"План разбивает спеку на именованные упорядоченные задачи. Это документ, который реализующий агент читает в начале каждой сессии.\"],\"p8ft+P\":[\"Установить Archcore →\"],\"pBhPVm\":[\"Посмотрите, как работают скиллы\"],\"pE5aaU\":[\"Настройка MCP — рутина\"],\"pJIaEj\":[\"Скажите «сделай это нашим стандартом», и трек решений предложит продолжающий каскад <0>spec → rule → guide</0>.\"],\"pLRjBH\":[\"Ставит хуки сессии\"],\"pQuaQO\":[\"Самый удобный вариант для Claude Code, Cursor и Codex CLI. Семь слэш-команд, автоматическая подгрузка контекста, guardrails.\"],\"pRMeEZ\":[\"Что делает archcore init\"],\"pSW7cy\":[\"Убедитесь, что слой контекста содержит ровно то, что вы ждёте, прежде чем начнёте править код с этим контекстом.\"],\"pTn+6e\":[\"Спланируйте функцию\"],\"pVg5+D\":[\"Один и тот же запрос — без инструкций и с ними\"],\"pWCBOZ\":[\"Решения и ограничения записаны, а не выведены из кода.\"],\"pcBorA\":[\"Записи о проверках\"],\"pfFb96\":[\"Скажите агенту, что вам нужно. Archcore это запишет.\"],\"piilWC\":[\"Два вызова <0>create_document</0>: одно правило, один гайд.\"],\"pmLwkw\":[\"Локальный MCP в вашем репозитории\"],\"pxwbCu\":[\"Плагин работает в Claude Code, Cursor 2.5+, Codex CLI 0.117+ и GitHub Copilot CLI. CLI работает с любым агентом, поддерживающим MCP: эти четыре плюс Gemini CLI, OpenCode, Roo Code и Cline. Он ещё и скриптуется в CI.\"],\"pz9/Fg\":[\"Плагин работает в Claude Code, Cursor 2.5+, Codex CLI 0.117+ и GitHub Copilot CLI. CLI работает с любым агентом, поддерживающим MCP, — эти четыре плюс Gemini CLI, OpenCode, Roo Code, Cline — и скриптуется в CI.\"],\"pzzo/i\":[\"Плагин Archcore загружает вашу архитектуру, правила и решения в Claude Code, Cursor и Codex CLI — чтобы агент перестал угадывать и начал следовать команде.\"],\"q1wpjZ\":[\"Что попробовать дальше.\"],\"q2TgoO\":[\"Проблема\"],\"q3rQ5K\":[\"<0>archcore init</0> создаёт <1>.archcore/</1>, находит агентов, которыми вы уже пользуетесь, и подключает MCP, хуки и плагин к выбранным хостам.\"],\"q3tG2r\":[\"Ваши первые пятнадцать минут\"],\"qBeBer\":[\"Материалы о поддержке хостов\"],\"qNE6UV\":[\"Плагин Archcore загружает вашу архитектуру, правила и решения в Claude Code, Cursor, Codex и Copilot CLI, чтобы агент следовал правде вашей команды.\"],\"qOGZ1r\":[\"<0>refund-policy.rule.md</0>, ограничение, которое ваши правки обязаны соблюдать.\"],\"qhjKMk\":[\"У Archcore открытый исходный код, и мы разрабатываем его публично. Звезда помогает большему числу разработчиков его найти и подсказывает нам, куда двигаться дальше.\"],\"qln1Bv\":[\"CLI ставится как предусловие — плагин вызывает <0>archcore</0> из PATH.\"],\"qmJKJ7\":[\"Готово.\"],\"qncZ5S\":[\"Все восемь агентов ниже могут читать одни и те же документы проекта через MCP. Поддержка хуков у них различается.\"],\"que8JV\":[\"Дальше по кругу. Следующий план стартует со всем, что записали три предыдущих шага, и ничего из этого не покидает репозиторий.\"],\"qyliLY\":[\"Archcore хранит решения, спецификации и правила вашего проекта прямо в репозитории.\"],\"qzs846\":[\"Свернуть инструкции ↑\"],\"r1Tsx/\":[\"Сохраните решение\"],\"r5UhB2\":[\"Попросите агента записать решение как ADR в Git.\"],\"r5p6H5\":[\"Контекст проекта в Git для любого AI-агента.\"],\"rCu87Y\":[\"Контекст едет вместе с кодовой базой, через Git.\"],\"rEv59f\":[\"Код, подходящий этому репозиторию с первого раза\"],\"rLdlgZ\":[\"Вставьте текст в файл инструкций проекта и откройте новую сессию.\"],\"rOVXme\":[\"Любой агент\"],\"rPqCpz\":[\"Slash-команды, скиллы и защитные проверки работают внутри Claude Code, Cursor, Codex CLI и GitHub Copilot. Остальные агенты добираются до того же контекста через MCP и session-хуки.\"],\"rYGKp9\":[\"Подключите контекст проекта к инструментам, которыми вы уже пользуетесь.\"],\"rcSlAD\":[\"Одна установка. На Claude Code, Cursor, Codex CLI и Copilot плагин ставится вместе с ней.\"],\"rfjyRs\":[\"<0>use-postgres.adr.md</0> — решение, которому подчиняются ваши запросы.\"],\"rjGI/Q\":[\"Приватность\"],\"rjZpLn\":[\"Материалы\"],\"rmSPzx\":[\"Где живут мои документы?\"],\"rtjKSQ\":[\"No command, no paste, no reminder. Each session also opens with a recap of what is decided and what is in progress.\"],\"ruALJv\":[\"Решения застряли в истории чата\"],\"ruLG1m\":[\"Установите в Codex:\"],\"s0KACp\":[\"Зачем здесь CLI: больше контроля. Эти запросы напрямую вставляются в GitHub Actions или pre-commit хуки. Шаг аудита превращается в настоящий барьер перед мержем.\"],\"sEHcCr\":[\"Одна установка даёт Claude Code, Cursor, Codex и Copilot память, которая живёт рядом с кодом и подставляется автоматически во время правок, а slash-команды фиксируют новые решения по ходу работы.\"],\"sG0Guz\":[\"Сначала установите CLI\"],\"sGJEPY\":[\"Готовит черновик <0>auth-redesign.plan.md</0> с фазами, критериями приёмки и зависимостями.\"],\"sIuJdc\":[\"Плагин или CLI\"],\"sJVtY8\":[\"Нет. Плагин работает на CLI под капотом — поставь плагин и получишь оба. Нужен только базовый слой контекста? Поставь CLI отдельно.\"],\"sVQohZ\":[\"Рантайм для Claude Code, Cursor и Codex CLI. Семь slash-команд, автоматическая инъекция контекста, защита от ошибок.\"],\"scu3wk\":[\"Модель\"],\"seC3dL\":[\"Пишет конфиг MCP\"],\"stWWAx\":[\"Запустите в PowerShell:\"],\"sxdLrw\":[\"Цикл\"],\"t+6jAV\":[\"Всё, что знает агент, лежит в файле: его можно прочитать, провести через пул-реквест и перенести в любой агент. Обычный Markdown внутри репозитория, версионируется вместе с кодом. Без базы данных, без внешних сервисов, и ничего не хранится там, где вы не можете это поправить.\"],\"t/X/Pg\":[\"Без Archcore\"],\"t3oGd1\":[\"Задокументировать то, что уже живёт в коде\"],\"tMAnJ2\":[\"Агент вызывает <0>create_document</0> через MCP с <1>type=adr</1>.\"],\"tPheNi\":[\"<0>Почему контексту проекта место в Git</0> разбирает каждое утверждение, включая то, чем жертвуют альтернативы.\"],\"tQtrme\":[\"Создаёт .archcore/\"],\"tZ9kai\":[\"Когда забыли, какая команда подходит\"],\"tbxKaR\":[\"Явный\"],\"tmTOv8\":[\"Запускайте перед мёрджем всего, что трогает код под захваченными документами — три секунды, один отчёт.\"],\"twg6kz\":[\"Материалы по интеграции агентов\"],\"u28snm\":[\"Код, который разъехался со спецификацией, где он описан.\"],\"uAQUqI\":[\"Статус\"],\"uAtbWa\":[\"Посмотрите репозитории CLI и плагина.\"],\"uFXPzN\":[\"Должен прийти ответ «пока нет» (или список, если документы уже создавали).\"],\"uHwiUj\":[\"Понять объём до того, как писать\"],\"uJCbNO\":[\"Если агент сообщает, что инструмента или файла инструкций нет, завершите эту настройку до начала работы.\"],\"uUZHM8\":[\"Загрузить уже принятые решения перед тем, как менять код\"],\"uc5vD1\":[\"Авто-загрузка в начале сессии\"],\"ucoezF\":[\"Задокументировать то, что уже есть в коде\"],\"ud0xNG\":[\"Модуль, который понимает один человек, становится спецификацией, по которой работает агент.\"],\"ujpps9\":[\"Готовит <0>notifications.spec.md</0>: интерфейсы, инварианты, крайние случаи.\"],\"umtlfT\":[\"Разработка по спецификациям с плагином Archcore\"],\"us2RbS\":[\"Папка прямо в репозитории для решений, правил, планов, гайдов и спецификаций.\"],\"ut48h4\":[\"Каждый шаг — гейт: посмотрите черновик, отредактируйте, примите и двигайтесь дальше.\"],\"utfu5D\":[\"Что вы хотите сделать с Archcore?\"],\"uvy6R7\":[\"Смотреть пример →\"],\"uwce85\":[\"Страница обновлена\"],\"v0fg68\":[\"Показывает всё это одним превью — до вашего единственного подтверждения ничего не пишется.\"],\"v4PYhA\":[\"Сохраните CLAUDE.md, AGENTS.md, .cursor/rules и docs/. Попросите агента оформить нужный раздел как документ Archcore, затем проверьте результат.\"],\"vAadO4\":[\"Готовит черновик <0>notifications.spec.md</0> — интерфейсы, инварианты, краевые случаи.\"],\"vDgOkn\":[\"Файлы с инструкциями разрастаются в стену текста.\"],\"vEkZZU\":[\"Зачем здесь CLI: больше контроля — каждое действие — это именованный MCP-вызов, который можно переиграть, версионировать или гонять в CI.\"],\"vEqTS8\":[\"Три вызова <0>create_document</0> через MCP — один ADR, одно правило, один гайд.\"],\"vJ93wl\":[\"Хуки подставляют правила и спеки, относящиеся к файлу, который правит агент, а каждая сессия начинается со сводки того, что решено и что в работе.\"],\"vP6Q4p\":[\"Там, где есть поддержка хуков сессии, агент получает список документов и сводку принятых решений и текущей работы.\"],\"vPeGqc\":[\"CLI\"],\"vTpzZT\":[\"Превратить знание в головах в версионируемые доки — модули, API, интеграции — прямо в репозитории.\"],\"vWsw6F\":[\"Четыре скилла на одной задаче\"],\"vXHjmJ\":[\"<0>archcore init</0> Одна команда, четыре вещи настроены за вас.\"],\"vcpc5o\":[\"Закрыть меню\"],\"vhoDu1\":[\"Версионируемый\"],\"vigmH3\":[\"Установка, быстрый старт, захват кода или использование контекста — выберите путь.\"],\"vkyJRg\":[\"Изменения контекста уезжают тем же пул-реквестом, что и код.\"],\"vl6cdW\":[\"Запустите это в репозитории, с которым собираетесь работать. Он найдёт агентов, которые у вас уже стоят, и подключит их.\"],\"vnWhge\":[\"Archcore Plugin — память репозитория в Claude Code, Cursor, Codex\"],\"vvdr0c\":[\"2. Добавьте инструкции\"],\"vwbixt\":[\"Что вы получаете после init\"],\"vxDIgL\":[\"Попробуйте в своём репозитории.\"],\"vyx1yD\":[\"Плагин Archcore приносит spec-driven разработку и автоматический контекст проекта в Claude Code, Cursor, Codex CLI и GitHub Copilot CLI. Спецификации, архитектура, решения, правила и планы живут в Git и применяются, пока агент работает.\"],\"vzB39z\":[\"Если решение ещё не принято, спросите «стоит ли переходить на gRPC», и получите RFC, а к нему шаг резолюции на потом.\"],\"w51IU1\":[\"Самый отполированный опыт для Claude Code, Cursor, Codex CLI и GitHub Copilot CLI. Четыре slash-команды, автоматическая подстановка контекста, ограждения.\"],\"w6Mlja\":[\"Перед правками подгрузите нужные правила и ADR, после правок — запустите аудит.\"],\"w6qPWt\":[\"Production\"],\"wIsV8p\":[\"Превратите идею на обычном языке в PRD → спеку → план.\"],\"wMn9kl\":[\"Затем скопируйте <0>cursor.mcp.json</0> из корня установленного плагина в <1>~/.cursor/mcp.json</1>. Cursor не регистрирует MCP плагина автоматически.\"],\"wPl7Jj\":[\"Начните с одной папки, которую агент раз за разом переоткрывает. На выходе обычно получается <0>.spec.md</0>, контракт с описанием того, что модуль гарантирует.\"],\"wQZovf\":[\"Каждый раз заново вставляете контекст\"],\"wTz2x8\":[\"Трек <0>sdd</0> по умолчанию ставит остановку <1>.spec.md</1> между PRD и планом.\"],\"wV02qE\":[\"В новом диалоге наберите:\"],\"wWtUa/\":[\"Четыре скилла Archcore по порядку\"],\"wdLnb1\":[\"Проверьте мою ветку перед мержем.\"],\"wdxz7K\":[\"Источник\"],\"wfkzaR\":[\"Установка Archcore\"],\"whludS\":[\"Введите рабочий email\"],\"wjUIH3\":[\"Плагин (рекомендуем)\"],\"wlddFX\":[\"Нет. В начале сессии агент получает компактный индекс ваших документов. Полные документы подтягиваются по требованию через MCP: поиском, по связям, по одиночным чтениям, а не грузятся целиком.\"],\"wnf4ZZ\":[\"Правила с областью действия\"],\"wqKB4i\":[\"Никакой непрозрачной памяти агента\"],\"wuMIXp\":[\"Документы хранятся в Markdown с метаданными YAML. Вы сами выбираете папки для них. У каждого агента своя конфигурация MCP.\"],\"x2/sbs\":[\"Без команд — просто попросите внести правку:\"],\"x4RuFo\":[\"На главную\"],\"x4zJr+\":[\"Хуки сессии подгружают правила и ADR для того, что вы редактируете.\"],\"xCwEOL\":[\"Настройте Archcore в этом репозитории.\"],\"xF9XI5\":[\"Настройте контекст проекта с Archcore CLI\"],\"xGL0/j\":[\"Каталог .archcore/ с шаблонами и конфигом для 19 типов документов в трёх слоях: vision (PRD, idea, plan, RnD, MRD, BRD, URD, BRS, StRS, SyRS, SRS), knowledge (ADR, RFC, rule, guide, doc, spec) и experience (task-type, CPAT).\"],\"xKVao+\":[\"Один бинарник, без демона и аккаунта. После установки <0>archcore init</0> создаст <1>.archcore/</1>, зарегистрирует MCP и поставит session-хуки для каждого найденного агента.\"],\"xMDBGv\":[\"Добавьте rate limiting в публичный API.\"],\"xROOPM\":[\"Нужны ли внешние сервисы?\"],\"xVY8bN\":[\"Маркетплейс или локальная директория\"],\"xchbkO\":[\"Всё пишется в <0>.archcore/</0> обычным markdown — вы смотрите диф как в любом коммите. То же подтверждение настраивает конфиги хостов, поэтому коллеги на одном лишь CLI тоже всё получат.\"],\"xhOLPK\":[\"CLI — один бинарь · Plugin — слэш-команды.\"],\"xmkhP0\":[\"Archcore CLI создаёт <0>.archcore/</0>, настраивает MCP и хуки и позволяет агентам читать и записывать решения, правила, планы и гайды прямо из Git.\"],\"xmnani\":[\"Короткий интерактивный тур по Archcore: когда использовать плагин, когда — CLI, и как подключить контекст к вашему AI-агенту — за 3-5 шагов.\"],\"xnX3WK\":[\"Трек <0>product</0> по умолчанию — это idea → PRD → план. Переключитесь на <1>--track feature</1>, когда нужен ещё слой спецификации.\"],\"xst0jS\":[\"<0>Открытый исходный код, разработка на виду.</0> Звезда помогает большему числу разработчиков его найти.\"],\"xszCdB\":[\"Каталог .archcore/ с шаблонами и конфигом для 19 типов документов в трёх слоях — vision (PRD, idea, plan, RnD, MRD, BRD, URD, BRS, StRS, SyRS, SRS), knowledge (ADR, RFC, rule, guide, doc, spec) и experience (task-type, CPAT).\"],\"y0bG43\":[\"Claude Code · Cursor · Codex CLI · Copilot · Gemini CLI · любой MCP-агент\"],\"y2HMia\":[\"Один модуль уже захвачен. Накопительный эффект Archcore приходит, когда захвачены те 3-5 модулей, которые агент постоянно переоткрывает.\"],\"yHrk88\":[\"Проверка\"],\"yLlBaq\":[\"Меняйте агента, не собирая контекст проекта заново.\"],\"yUMDgl\":[\"Claude Code, Cursor, Codex, Copilot — один источник правды.\"],\"yWdHrv\":[\"Агент читает ваш код. Он не читает рассуждения, которые за ним стоят.\"],\"yXV0D+\":[\"Четыре: /archcore:init (первая настройка), /archcore:plan (от идеи к плану с границами задачи), /archcore:document (записать решение или описать существующий код) и /archcore:review (сверить изменения с документами). Если среда поддерживает хуки перед записью, нужные правила и спецификации поступают автоматически до правок. В остальных средах тот же контекст проекта доступен через MCP.\"],\"yaO9ql\":[\"Агент запускает <0>search_documents</0>, передавая путь к папке как запрос.\"],\"ycMRr6\":[\"Два шага — оба обязательны.\"],\"yeSfrS\":[\"Вы должны увидеть <0>use-postgres.adr.md</0>, <1>postgres-only.rule.md</1> и <2>postgres-migration.guide.md</2>.\"],\"yj8K9P\":[\"Проход по всей базе знаний, если добавить <0>--deep</0>.\"],\"yn3Cdh\":[\"Структурный\"],\"ynx5wp\":[\"Руководство по интеграции\"],\"ytdGKR\":[\"Archcore держит ваши решения, правила и архитектуру структурированными документами в репозитории и отдаёт их агенту через MCP до того, как он начнёт править код.\"],\"yzSsDu\":[\"Вам не нужно помнить команду «загрузить контекст». Хуки делают это при каждой правке и в каждом новом диалоге.\"],\"z3fqXo\":[\"Without the instructions\"],\"z3vrN8\":[\"Нужный контекст приходит до вашей правки.\"],\"z5LLiI\":[\"Плагин Archcore загружает вашу архитектуру, правила и решения в Claude Code, Cursor, Codex CLI и GitHub Copilot CLI — чтобы агент перестал угадывать и начал следовать правде вашей команды.\"],\"z9cjEv\":[\"Она создаёт .archcore/ и настраивает выбранных вами агентов. Документы проекта создаются через MCP или с помощью навыков плагина.\"],\"zAfFJM\":[\"Каждая сессия начинается со сводки: что решено и что в работе. Перейдёте к другому агенту, и он прочитает ту же папку.\"],\"zBGJeM\":[\"Типизированные документы со связями, а не один разрастающийся файл.\"],\"zPZYX5\":[\"Решения перестают умирать в чате\"],\"zS24Wp\":[\"Спросит подтверждения перед записью — тип можно переопределить, черновик отредактировать.\"],\"zSGjmS\":[\"Bash — одна curl-строчка.\"],\"zX7gkY\":[\"ваши соглашения\"],\"zXzyLc\":[\"Запустите внутри Claude Code:\"],\"ze71F9\":[\"Зачем здесь CLI: больше контроля — каждое действие — это именованный MCP-вызов, который можно переиспользовать, версионировать или гонять в CI.\"],\"zgIyTw\":[\"Зачем здесь CLI: больше контроля — вы выбираете тип документа, путь и момент, когда агент пишет. Работает с любым MCP-агентом (Copilot, Gemini CLI, OpenCode, Cline).\"],\"zgi53N\":[\"Что такое память репозитория?\"],\"zsLXGK\":[\"Проверено частично\"],\"zucql+\":[\"Меню\"],\"zzOhVU\":[\"Одна команда из маркетплейса.\"]}")as Messages;